static inline bool is_fast_dtype(const torch::Tensor& t) {
    return t.dtype() == torch::kFloat32 || t.dtype() == torch::kFloat16 ||
           t.dtype() == torch::kBFloat16;
}

torch::Tensor fused_sigmoid_forward(torch::Tensor input, int config) {
    if (!input.is_cuda()) input = input.cuda();

    // Harness may hand us non-contiguous / non-fp32 data: normalize, never reject.
    if (!input.is_contiguous()) input = input.contiguous();
    if (!is_fast_dtype(input)) input = input.to(torch::kFloat32);

    auto output = torch::empty_like(input);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    fused_sigmoid_launcher(
        output.data_ptr<float>(),
        input.data_ptr<float>(),
        static_cast<int>(input.numel()),
        config,
        stream
    );

    return output;
}

