#include <cuda_runtime.h>

// Fused sigmoid for MetaX C500 (warp 64, 104 SMs).
// Memory-traffic-bound single pass: y = 1.0f / (1.0f + expf(-x)).
// float2 vectorization + fixed grid-stride loop keeps the grid coarse
// (known-good pattern on this device: ~1300 GB/s vs ~600 GB/s scalar).

__device__ __forceinline__ float sigmoidf(float x) {
    return 1.0f / (1.0f + expf(-x));
}

template<int BLOCK_SIZE>
__global__ void sigmoid_kernel(float* __restrict__ output,
                               const float* __restrict__ input,
                               int size) {
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;

    int i = tid * 2;
    const int last = size - 1;

    // Vectorized body: each thread handles 2 floats per iteration.
    for (; i + 1 < size; i += stride * 2) {
        float2 a, b;
        a = *reinterpret_cast<const float2*>(input + i);
        b = *reinterpret_cast<const float2*>(input + i + stride);
        float2 o;
        o.x = sigmoidf(a.x);
        o.y = sigmoidf(a.y);
        *reinterpret_cast<float2*>(output + i) = o;
        float2 o2;
        o2.x = sigmoidf(b.x);
        o2.y = sigmoidf(b.y);
        *reinterpret_cast<float2*>(output + i + stride) = o2;
    }
    // Tail for odd-sized tensors (and the second half of the last pair).
    for (; i < size; i += stride) {
        output[i] = sigmoidf(input[i]);
    }
    (void)last;
}

extern "C" void fused_sigmoid_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int threads = 256;  // 4 warps of 64
    // Fixed, coarse grid: 1024 blocks max so each SM gets ~10 blocks and
    // the grid-stride loop amortizes launch overhead on large tensors.
    int blocks = (size + threads * 2 - 1) / (threads * 2);
    if (blocks > 1024) blocks = 1024;
    if (blocks < 1) blocks = 1;

    switch (config) {
        case 0:
            sigmoid_kernel<256><<<blocks, threads, 0, stream>>>(output, input, size);
            break;
        case 1: {
            const int t = 512;
            int b = (size + t * 2 - 1) / (t * 2);
            if (b > 512) b = 512;
            if (b < 1) b = 1;
            sigmoid_kernel<512><<<b, t, 0, stream>>>(output, input, size);
            break;
        }
        default:
            sigmoid_kernel<256><<<blocks, threads, 0, stream>>>(output, input, size);
    }
}

