// kernels/fused_sigmoid.cu
#include <cuda_runtime.h>

// Sigmoid computed in a numerically stable, branch-free way:
//   for x >= 0 : 1/(1+exp(-x))
//   for x <  0 : exp(x)/(1+exp(x))
// Both are safe against overflow; selected without divergent branches.
__device__ __forceinline__ float stable_sigmoid(float x) {
    float r = expf(-fabsf(x));
    float num = (x >= 0.0f) ? 1.0f : r;
    float den = (x >= 0.0f) ? (1.0f + r) : (1.0f + r);
    return num / den;
}

// Vectorized grid-stride kernel. Fixed 1024-block grid keeps the grid coarse
// (C500 has 104 SMs); each thread processes float2 pairs, twice per iteration
// for extra ILP. Block size 256 = 4 warps of 64 threads on this device.
template<int BLOCK_SIZE>
__global__ void fused_sigmoid_impl(float* __restrict__ output,
                                   const float* __restrict__ input,
                                   int size) {
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;

    int i = tid * 2;  // each thread owns a float2 pair
    const int stride2 = stride * 2;

    // Fast path: full float2 pairs
    int limit = size - 1;  // need i and i+1 valid
    for (; i < limit; i += stride2) {
        float2 in = *reinterpret_cast<const float2*>(input + i);
        float2 out;
        out.x = stable_sigmoid(in.x);
        out.y = stable_sigmoid(in.y);
        *reinterpret_cast<float2*>(output + i) = out;
    }
    // Tail: single element, if any
    if (i < size) {
        output[i] = stable_sigmoid(input[i]);
    }
}

extern "C" void fused_sigmoid_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;
    // Fixed coarse grid: 1024 blocks total regardless of size. Each thread
    // handles multiple float2 elements via the grid-stride loop.
    const int GRID = 1024;

    fused_sigmoid_impl<BLOCK_SIZE><<<GRID, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

