#include <cuda_runtime.h>

// Fused single-pass leaky_relu for MetaX C500 (warp size 64, 104 SMs).
// Memory-bound elementwise op: one pass over 512M floats.
// float4 vectorization (16B loads/stores) + fixed 1024-block grid-stride loop.

__global__ void leaky_relu_kernel4(
    float* __restrict__ output,
    const float4* __restrict__ input,
    unsigned long long count4,
    float slope
) {
    const unsigned long long stride = (unsigned long long)blockDim.x * gridDim.x;
    unsigned long long idx = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;

    // Grid-stride loop: each thread handles 16 bytes per iteration.
    while (idx < count4) {
        float4 v = input[idx];
        float4 o;
        o.x = fmaximumf(v.x, 0.0f) + (fminimumf(v.x, 0.0f) * slope);
        o.y = fmaximumf(v.y, 0.0f) + (fminimumf(v.y, 0.0f) * slope);
        o.z = fmaximumf(v.z, 0.0f) + (fminimumf(v.z, 0.0f) * slope);
        o.w = fmaximumf(v.w, 0.0f) + (fminimumf(v.w, 0.0f) * slope);
        output[idx] = o;
        idx += stride;
    }
}

extern "C" void leaky_relu_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    float negative_slope,
    cudaStream_t stream
) {
    if (size == 0) return;

    // Align pointers to 16B for float4 access.
    bool aligned = (((uintptr_t)input & 15ULL) == 0) && (((uintptr_t)output & 15ULL) == 0);

    if (aligned) {
        const int BLOCK = 256;          // 4 warps of 64 threads
        const int GRID = 1024;          // fixed grid: 4M elements per pass, stride handles rest
