            const float* inp = input + count4 * 4;
            float* out = output + count4 * 4;
            // Simple scalar 1-thread-per-element fallback for the tail.
            // Kept tiny: at most 3 elements.
            for (unsigned long long i = 0; i < rem; ++i) {
                float v = inp[i];
                out[i] = (v > 0.0f) ? v : v * negative_slope;
            }
        }
    } else {
        // Unaligned fallback: scalar path (rare; PyTorch tensors are 256B-aligned).
        const int BLOCK = 256;
        unsigned long long grid = (size + (unsigned long long)BLOCK - 1ULL) / BLOCK;
        if (grid > 1024ULL) grid = 1024ULL;
        // Scalar kernel inline via thrust-free manual loop:
        // launch a simple kernel
        struct ScalarKernel {
            __device__ static void run(float* o, const float* i, unsigned long long n, float s) {}
        };
        // Fallback implemented with a small dedicated kernel below.
        leaky_relu_scalar<<<(unsigned int)grid, BLOCK, 0, stream>>>(
            output, input, size, negative_slope);
