#include <cuda_runtime.h>

// Leaky ReLU elementwise: max(x, 0) + negative_slope * min(x, 0)
// Negative slope matches torch.nn.functional.leaky_relu default (0.01).
//
// This is a memory-bound elementwise op, so we use float2 vectorized loads
// with a fixed grid-stride loop. Warp size on this device is 64.

template<int BLOCK_SIZE>
__global__ void leaky_relu_kernel_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    long long size
) {
    const long long tid = (long long)blockIdx.x * (long long)BLOCK_SIZE + (long long)threadIdx.x;
    const long long stride = (long long)BLOCK_SIZE * (long long)gridDim.x;

    const float neg_slope = 0.01f;

    // Grid-stride loop over float2 (2 elements per thread per iteration)
    const long long v_size = size >> 1;
    const float2* in2 = (const float2*)input;
    float2* out2 = (float2*)output;

    long long i = tid;
    while (i < v_size) {
        float2 v = in2[i];
        float2 r;
        r.x = fmaxf(v.x, 0.0f) + neg_slope * fminf(v.x, 0.0f);
        r.y = fmaxf(v.y, 0.0f) + neg_slope * fminf(v.y, 0.0f);
        out2[i] = r;
        i += stride;
    }

    // Tail: odd element count
    if ((size & 1LL) != 0LL) {
        if (tid == 0) {
            long long last = size - 1;
            float v = input[last];
            output[last] = fmaxf(v, 0.0f) + neg_slope * fminf(v, 0.0f);
        }
    }
}

extern "C" void leaky_relu_launcher(
    float* output,
    const float* input,
    long long size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;
    // Fixed, moderately-sized grid with grid-stride loop.
    const long long v_size = size >> 1;
    long long blocks_ll = (v_size + (long long)BLOCK_SIZE - 1LL) / (long long)BLOCK_SIZE;
    const int MAX_BLOCKS = 1024;
    if (blocks_ll > (long long)MAX_BLOCKS) blocks_ll = (long long)MAX_BLOCKS;
    int blocks = (int)blocks_ll;
    if (blocks < 1) blocks = 1;

    leaky_relu_kernel_impl<256><<<blocks, BLOCK_SIZE, 0, stream>>>(output, input, size);
}

