#include <cuda_runtime.h>

// Fused leaky_relu: out = x > 0 ? x : 0.01f * x
// Memory-bound elementwise op; vectorized with float4 loads/stores and a
// fixed 1024-block grid-stride loop (coarse grid proven faster on C500).

template<int BLOCK_SIZE>
__global__ void leaky_relu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    const float negative_slope = 0.01f;
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // float4 phase: 4 elements per thread, aligned
    int aligned_size = size & ~3;
    int4* out4 = (int4*)output;
    const int4* in4 = (const int4*)input;
    int n4 = aligned_size >> 2;
    int stride4 = stride >> 2;

    for (int i = tid; i < n4; i += stride4) {
        float4 v;
        v.x = ((float*)in4)[i * 4 + 0];
        v.y = ((float*)in4)[i * 4 + 1];
        v.z = ((float*)in4)[i * 4 + 2];
        v.w = ((float*)in4)[i * 4 + 3];
        float4 r;
        r.x = fmaxf(v.x, negative_slope * v.x);
        r.y = fmaxf(v.y, negative_slope * v.y);
        r.z = fmaxf(v.z, negative_slope * v.z);
        r.w = fmaxf(v.w, negative_slope * v.w);
        ((float4*)out4)[i] = r;
    }

    // scalar tail
    for (int i = aligned_size + tid; i < size; i += stride) {
        float v = input[i];
        output[i] = fmaxf(v, negative_slope * v);
    }
}

extern "C" void leaky_relu_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    const int BLOCK_SIZE = 256;
    const int GRID_SIZE = 1024;
    leaky_relu_kernel<BLOCK_SIZE><<<GRID_SIZE, BLOCK_SIZE, 0, stream>>>(
        output, input, size
    );
}

