// Fused hardtanh: clamp(x, -1, 1) == max(-1, min(1, x)).
// Single-pass, float2 vectorized, fixed 1024-block grid-stride loop
// (measured best on C500: 64-wide warps, memory-traffic-bound elementwise).
__global__ void hardtanh_kernel_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size
) {
    const int64_t tid = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    const int64_t stride = (int64_t)blockDim.x * gridDim.x;

    const int64_t n2 = size >> 1;
    const bool odd = (size & 1) != 0;

    for (int64_t i = tid; i < n2; i += stride) {
        float2 v = reinterpret_cast<const float2*>(input)[i];
        v.x = fmaxf(-1.0f, fminf(1.0f, v.x));
        v.y = fmaxf(-1.0f, fminf(1.0f, v.y));
        reinterpret_cast<float2*>(output)[i] = v;
    }

    if (odd && tid == 0) {
        float v = input[size - 1];
        output[size - 1] = fmaxf(-1.0f, fminf(1.0f, v));
    }
}

extern "C" void hardtanh_kernel_launcher(
    float* output,
    const float* input,
    int64_t size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int block = 256;
    int grid = (int)((size + 1) / 2 + block - 1) / block;  // elements in float2 units
    if (grid < 1) grid = 1;
    if (grid > 1024) grid = 1024;  // fixed grid: grid-stride loop handles the tail

    hardtanh_kernel_impl<<<grid, block, 0, stream>>>(output, input, size);
}

