// Memory-bound on C500: use float2 vectorized loads/stores with a fixed
// 1024-block grid-stride loop so the 104 SMs stay saturated. Warp size is 64.
// 1024 blocks * 256 threads = 262144 threads; each handles 2 elements per step.

__global__ void hardtanh_kernel(const float2* __restrict__ in, float2* __restrict__ out, int64_t n2) {
    int64_t tid = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;

    for (int64_t i = tid; i < n2; i += stride) {
        float2 v = in[i];
        float2 r;
        r.x = fminf(fmaxf(v.x, -1.0f), 1.0f);
        r.y = fminf(fmaxf(v.y, -1.0f), 1.0f);
        out[i] = r;
    }
}

// Tail kernel (scalar) for the odd element when n is not even.
__global__ void hardtanh_tail_kernel(const float* __restrict__ in, float* __restrict__ out, int64_t idx) {
    if (threadIdx.x == 0 && blockIdx.x == 0) {
        out[idx] = fminf(fmaxf(in[idx], -1.0f), 1.0f);
    }
}

