        const int GRID = 1024;
        hardtanh_kernel<<<GRID, BLOCK, 0, stream>>>(
            reinterpret_cast<const float2*>(in),
            reinterpret_cast<float2*>(out),
            n2);
    }
    if (n & 1) {
        hardtanh_tail_kernel<<<1, 32, 0, stream>>>(in, out, n - 1);
