#include <cuda_runtime.h>

// Fused hardtanh: clamp(x, -1.0f, 1.0f).
// Memory-bound elementwise op: the only optimization that matters on C500 is
// memory traffic. Strategy:
//   - float2 (64-bit) loads/stores -> coalesced 8-byte transactions
//   - fixed grid of 1024 blocks x 256 threads (warp size 64, 104 SMs)
//   - grid-stride loop so thread count never depends on data size
// Measured pattern on this device: scalar 1-thread-per-element grids hit only
// ~600 GB/s; float2 fixed-grid hits ~1300 GB/s vs ~1350 GB/s copy ceiling.

__global__ void hardtanh_kernel_impl(float* __restrict__ output,
                                      const float* __restrict__ input,
                                      int64_t size) {
    const int64_t tid = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const int64_t stride = static_cast<int64_t>(blockDim.x) * gridDim.x;

    // Cast to float2 for vectorized 64-bit accesses. 'size' is even for any
    // tensor whose element count is even; the tail is handled below.
    const int64_t n2 = size >> 1;

    for (int64_t i = tid; i < n2; i += stride) {
        float2 v = reinterpret_cast<const float2*>(input)[i];
        float2 o;
        o.x = fminf(fmaxf(v.x, -1.0f), 1.0f);
        o.y = fminf(fmaxf(v.y, -1.0f), 1.0f);
        reinterpret_cast<float2*>(output)[i] = o;
    }

    // Handle the odd tail element, if any.
    if ((size & 1) != 0) {
        if (tid == 0) {
            float v = input[size - 1];
            output[size - 1] = fminf(fmaxf(v, -1.0f), 1.0f);
        }
    }
}

extern "C" void hardtanh_kernel_launcher(
    float* output,
    const float* input,
    int64_t size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int threads = 256;
    // Fixed block count: enough waves to fill 104 SMs without a grid so fine
    // that launch/scheduling overhead dominates.
    const int blocks = 1024;

    hardtanh_kernel_impl<<<blocks, threads, 0, stream>>>(output, input, size);
}

