#include <cuda_runtime.h>

// Threshold: y = (x > t) ? x : 0   (nn.Threshold(threshold, 0))
//
// Performance design for MetaX C500 (warp size 64, 104 SMs):
//  - float2 vectorized loads/stores (coalesced 8-byte pairs)
//  - FIXED grid of 1024 blocks (fine enough to fill all 104 SMs several times,
//    coarse enough to avoid the per-block launch/scheduling overhead that a
//    one-thread-per-element grid hits on this device)
//  - grid-stride loop so each block processes a persistent chunk
//  - branch-free select via fmaxf to keep the SFU-free arithmetic cheap
//
// vectorized path handles the bulk; a scalar tail handles any odd remainder.

__global__ void threshold_kernel_vec2(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size,
    float threshold
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    const int v2_count = size >> 1;  // pairs

    // Each thread handles one float2 per grid-stride iteration.
    for (int i = tid; i < v2_count; i += stride) {
        float2 in = reinterpret_cast<const float2*>(input)[i];
        float2 out;
        out.x = (in.x > threshold) ? in.x : 0.0f;
        out.y = (in.y > threshold) ? in.y : 0.0f;
        reinterpret_cast<float2*>(output)[i] = out;
    }

    // Scalar tail for odd-sized input.
    if ((size & 1) != 0) {
        int last = size - 1;
        if (tid == 0) {
            float v = input[last];
            output[last] = (v > threshold) ? v : 0.0f;
        }
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void threshold_kernel_launcher(
    float* output,
    const float* input,
    int size,
    float threshold,
    cudaStream_t stream
) {
    // Fixed 1024-block grid with 256 threads/block => 256K threads.
    // With float2 that covers 512K elements per stride pass; the grid-stride
    // loop handles the remaining ~512M elements with full occupancy.
    const int blocks = 1024;
    const int threads = 256;

    threshold_kernel_vec2<<<blocks, threads, 0, stream>>>(
        output, input, size, threshold
    );
}

