#include <cuda_runtime.h>

// Vectorized (float4) fused tanh with fixed grid + grid-stride loop.
// Warp size is 64 on C500; 256 threads/block x 1024 blocks fully fills 104 SMs.
template<int BLOCK_SIZE>
__global__ void tanh_kernel_impl(float* __restrict__ output,
                                 const float* __restrict__ input,
                                 int size) {
    // Vectorize only when the base pointer is 16-byte aligned; the scalar
    // tail path covers everything else.
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    const int v_size = size >> 2;          // number of float4 elements
    const int rem = size - (v_size << 2);  // leftover scalar elements

    float4* out4 = reinterpret_cast<float4*>(output);
    const float4* in4 = reinterpret_cast<const float4*>(input);

    for (int i = tid; i < v_size; i += stride) {
        float4 v = in4[i];
        v.x = tanhf(v.x);
        v.y = tanhf(v.y);
        v.z = tanhf(v.z);
        v.w = tanhf(v.w);
        out4[i] = v;
    }

    // Scalar tail (at most 3 elements), handled by the first threads.
    int tail_start = v_size * 4;
    for (int i = tid; i < rem; i += stride) {
        output[tail_start + i] = tanhf(input[tail_start + i]);
    }
}

extern "C" void tanh_kernel_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    // Check 16-byte alignment of both pointers for the float4 path.
    bool aligned = ((reinterpret_cast<size_t>(input) & 0xF) == 0) &&
                   ((reinterpret_cast<size_t>(output) & 0xF) == 0);

    if (aligned) {
        const int BLOCK = 256;
        int blocks = 1024;
        if (size < (blocks * BLOCK * 4)) {
            int need = (size + BLOCK * 4 - 1) / (BLOCK * 4);
            if (need < blocks) blocks = need;
            if (blocks < 1) blocks = 1;
        }
        switch (config) {
            case 0: tanh_kernel_impl<256><<<blocks, 256, 0, stream>>>(output, input, size); break;
            case 1: tanh_kernel_impl<128><<<blocks * 2 > 65535 ? 65535 : blocks * 2, 128, 0, stream>>>(output, input, size); break;
            case 2: tanh_kernel_impl<512><<<blocks / 2 < 1 ? 1 : blocks / 2, 512, 0, stream>>>(output, input, size); break;
            default: tanh_kernel_impl<256><<<blocks, 256, 0, stream>>>(output, input, size); break;
        }
    } else {
        // Unaligned fallback: scalar grid-stride loop.
        const int BLOCK = 256;
        int blocks = (size + BLOCK - 1) / BLOCK;
        if (blocks > 1024) blocks = 1024;
        // Simple scalar path via the same template with size trick: use a
        // dedicated inline kernel to avoid float4 on unaligned data.
        // Implemented below as a lambda-free plain kernel launch.
        tanh_kernel_impl<256><<<blocks, BLOCK, 0, stream>>>(output, input, 0);  // size 0 => no-op
        // Scalar fallback kernel:
        scalar_tanh_kernel<<<blocks, BLOCK, 0, stream>>>(output, input, size);
    }
}

// Scalar fallback for unaligned buffers.
__global__ void scalar_tanh_kernel(float* __restrict__ output,
                                   const float* __restrict__ input,
                                   int size) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;
    for (int i = tid; i < size; i += stride) {
        output[i] = tanhf(input[i]);
    }
}

