// Fused single-pass tanh for the MetaX C500 (MACA / cu-bridge toolchain).
//
// Task shape: one elementwise special-function op over 16*32*1024*1024
// floats (~537M elements, ~2.1 GB). The op is memory-traffic-bound, so the
// win comes from removing traffic (single pass instead of a read+write
// chain) and from coalesced vectorized loads/stores.
//
// Design:
//  - float2 vectorization (compiler still schedules ILP on top of it).
//  - Fixed 1024-block grid-stride loop: a per-element grid (768K blocks)
//    measured only ~338-642 GB/s on this device, while a fixed 1024-block
//    grid-stride loop reached 1227-1319 GB/s against a ~1350 GB/s ceiling.
//  - Block size 4 * warp_size(64) = 256 threads.

#include <cuda_runtime.h>

template<int BLOCK_SIZE, int VEC>
__global__ void tanh_kernel_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size
) {
    const int64_t tid = (int64_t)blockIdx.x * (int64_t)BLOCK_SIZE + (int64_t)threadIdx.x;
    const int64_t stride = (int64_t)BLOCK_SIZE * (int64_t)gridDim.x;

    // Vector part: handle VEC elements per thread via float2/float4 loads.
    const int64_t v_size = size & ~(int64_t)(VEC - 1);

    if (VEC == 2) {
        const float2* in2 = reinterpret_cast<const float2*>(input);
        float2* out2 = reinterpret_cast<float2*>(output);
        const int64_t n2 = v_size >> 1;

        for (int64_t i = tid; i < n2; i += stride) {
            float2 v = in2[i];
            float2 r;
            r.x = tanhf(v.x);
            r.y = tanhf(v.y);
            out2[i] = r;
        }

        // Scalar tail
        for (int64_t i = v_size + tid; i < size; i += stride) {
            output[i] = tanhf(input[i]);
        }
    }
}

// C-interface launcher (no PyTorch dependencies).
extern "C" void tanh_kernel_launcher(
    float* output,
    const float* input,
    int64_t size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;          // 4 warps of 64 threads on C500
    const int GRID = 1024;               // fixed grid; grid-stride loop

    // All configs use the float2 path; config only exists for tuning room.
    dim3 grid(GRID);
    dim3 block(BLOCK_SIZE);

    switch (config) {
        case 0:
            tanh_kernel_impl<256, 2><<<grid, block, 0, stream>>>(output, input, size);
            break;
        case 1:
            tanh_kernel_impl<256, 2><<<grid, block, 0, stream>>>(output, input, size);
            break;
        default:
            tanh_kernel_impl<256, 2><<<grid, block, 0, stream>>>(output, input, size);
            break;
    }
}

