#include <cuda_runtime.h>

// Fused hardsigmoid: y = clamp(x/6 + 1/6, 0, 1)
// Memory-bound elementwise op on a 512*1024*1024 float32 tensor (~2 GiB/pass).
// Strategy: float4 vectorized loads/stores + fixed coarse grid-stride loop
// (measured sweet spot on MetaX C500: ~1024 blocks, avoids the fine-grid
// granularity trap that caps scalar kernels at ~600 GB/s).
// No SFU chain: division by 6 becomes multiply by reciprocal, clamp uses
// __saturatef (branch-free).

__global__ void hardsigmoid_kernel_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t size     // number of float elements
) {
    const float inv6 = 0.16666667163372039794921875f; // 1/6 in float

    size_t tid = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const size_t stride = static_cast<size_t>(blockDim.x) * gridDim.x;

    // Vector lane count: tid indexes float4 groups
    const size_t size4 = size >> 2;           // full float4 groups
    const size_t rem   = size - (size4 << 2); // tail elements

    float4* out4 = reinterpret_cast<float4*>(output);
    const float4* in4 = reinterpret_cast<const float4*>(input);

    for (size_t i = tid; i < size4; i += stride) {
        float4 v = in4[i];
        v.x = __saturatef(v.x * inv6 + inv6);
        v.y = __saturatef(v.y * inv6 + inv6);
        v.z = __saturatef(v.z * inv6 + inv6);
        v.w = __saturatef(v.w * inv6 + inv6);
        out4[i] = v;
    }

    // Tail: scalar handling of remaining elements
    size_t tail_base = size4 << 2;
    for (size_t j = tid; j < rem; j += stride) {
        size_t idx = tail_base + j;
        output[idx] = __saturatef(input[idx] * inv6 + inv6);
    }
}

extern "C" void hardsigmoid_kernel_launcher(
    float* output,
    const float* input,
    size_t size,
    cudaStream_t stream
) {
    if (size == 0) return;

    const int threads = 256;                  // 4 warps of 64
    // Fixed coarse grid: many elements per block via grid-stride loop.
    // 1024 blocks * 256 threads = 262144 threads; for 537M elements each
    // thread handles ~2048 float4s. Keep grid modest to maximize per-SM
    // occupancy and avoid the launch/granularity penalty.
    int blocks = 1024;
    const size_t size4 = size >> 2;
    const size_t needed = (size4 + threads - 1) / threads;
    if (static_cast<size_t>(blocks) > needed) {
        blocks = static_cast<int>(needed < 2147483647ULL ? needed : 2147483647ULL);
        if (blocks < 1) blocks = 1;
    }

    hardsigmoid_kernel_impl<<<blocks, threads, 0, stream>>>(output, input, size);
}

