#include <cuda_runtime.h>

// Fused hardsigmoid: out = clamp(x/6 + 0.5, 0, 1)
//   equivalently: x <= -3 -> 0 ; x >= 3 -> 1 ; else x/6 + 0.5
// Exact piecewise form avoids any SFU chain; purely compare + fma.
// Vectorized with float2 and a fixed ~1024-block grid-stride loop,
// which on the C500 (warp 64, 104 SMs) reaches the memory ceiling.

template<int BLOCK_SIZE>
__global__ void hardsigmoid_vec2_impl(float* __restrict__ output,
                                      const float* __restrict__ input,
                                      int size) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // float2 processing: each thread handles 2 consecutive elements
    int aligned = size & ~1;

    for (int i = tid * 2; i < aligned; i += stride * 2) {
        float2 v = *reinterpret_cast<const float2*>(input + i);
        float2 r;
        r.x = fminf(fmaxf(v.x * 0.16666667163372039794921875f + 0.5f, 0.0f), 1.0f);
        r.y = fminf(fmaxf(v.y * 0.16666667163372039794921875f + 0.5f, 0.0f), 1.0f);
        *reinterpret_cast<float2*>(output + i) = r;
    }

    // Tail: odd remaining element
    if (aligned < size) {
        int i = aligned + tid;
        if (i < size) {
            float v = input[i];
            output[i] = fminf(fmaxf(v * 0.16666667163372039794921875f + 0.5f, 0.0f), 1.0f);
        }
    }
}

extern "C" void fused_hardsigmoid_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK = 256;
    // Fixed grid of 1024 blocks (262144 threads) with grid-stride loop.
    // Handled pairs: 2 elements per thread per iteration.
    int blocks = 1024;

    switch (config) {
        case 0:
            hardsigmoid_vec2_impl<256><<<blocks, BLOCK, 0, stream>>>(output, input, size);
            break;
        case 1: {
            // Larger grid for very big tensors: one wave across all 104 SMs
            int pairs = (size + 1) / 2;
            int b = (pairs + BLOCK - 1) / BLOCK;
            if (b < 1024) b = 1024;
            if (b > 8192) b = 8192;
            hardsigmoid_vec2_impl<256><<<b, BLOCK, 0, stream>>>(output, input, size);
            break;
        }
        default:
            hardsigmoid_vec2_impl<256><<<blocks, BLOCK, 0, stream>>>(output, input, size);
    }
}

