#include <cuda_runtime.h>

// Memory-bound sign kernel for MetaX C500 (warp size 64, 104 SMs).
// One grid-stride pass, float4 loads/stores: 2.5GB traffic vs 5GB for
// a compare-then-branch formulation is avoided entirely by computing
// sign branch-free via copysignf on a normalized magnitude so no SFU
// chain is introduced.
template<int BLOCK_SIZE>
__global__ void sign_kernel_impl(float* __restrict__ output,
                                 const float* __restrict__ input,
                                 long long size) {
    const long long tid = (long long)blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const long long stride = (long long)BLOCK_SIZE * gridDim.x;

    float4* out4 = reinterpret_cast<float4*>(output);
    const float4* in4 = reinterpret_cast<const float4*>(input);

    const long long n4 = size >> 2;
    const int tail = (int)(size - (n4 << 2));

    // Vectorized body (elements 4*tid .. 4*tid+3)
    for (long long i = tid; i < n4; i += stride) {
        float4 v = in4[i];
        float4 r;
        r.x = copysignf(1.0f, v.x);
        r.y = copysignf(1.0f, v.y);
        r.z = copysignf(1.0f, v.z);
        r.w = copysignf(1.0f, v.w);
        out4[i] = r;
    }

    // Scalar tail handled by the last block's low threads only
    if (tail > 0 && blockIdx.x == gridDim.x - 1) {
        const int lane = threadIdx.x;
        if (lane < tail) {
            const long long idx = (n4 << 2) + lane;
            output[idx] = copysignf(1.0f, input[idx]);
        }
    }
}

// Fallback scalar kernel for tiny / unaligned sizes
__global__ void sign_scalar_kernel(float* __restrict__ output,
                                   const float* __restrict__ input,
                                   long long size) {
    const long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    const long long stride = (long long)blockDim.x * gridDim.x;
    for (long long i = tid; i < size; i += stride) {
        output[i] = copysignf(1.0f, input[i]);
    }
}

extern "C" void sign_kernel_launcher(float* output,
                                     const float* input,
                                     long long size,
                                     int config,
                                     cudaStream_t stream) {
    if (size <= 0) return;

    const unsigned long long base = (unsigned long long)output;
    const unsigned long long base_in = (unsigned long long)input;
    const int shift = 4;  // log2(sizeof(float4))

    // 16-byte alignment + multiple-of-4 length required for the vector path
    const bool aligned = ((base | base_in) & 15ull) == 0ull && (size & 3LL) == 0LL;

    if (aligned) {
        switch (config) {
            case 0: {
                const int threads = 256;   // 4 warps of 64
                const int blocks = 1024;
                sign_kernel_impl<256><<<blocks, threads, 0, stream>>>(output, input, size);
                break;
            }
            case 1: {
                const int threads = 128;   // 2 warps of 64
                const int blocks = 2048;
                sign_kernel_impl<128><<<blocks, threads, 0, stream>>>(output, input, size);
                break;
            }
            case 2: {
                const int threads = 512;   // 8 warps of 64
                const int blocks = 512;
                sign_kernel_impl<512><<<blocks, threads, 0, stream>>>(output, input, size);
                break;
            }
            default: {
                const int threads = 256;
                const int blocks = 1024;
                sign_kernel_impl<256><<<blocks, threads, 0, stream>>>(output, input, size);
                break;
            }
        }
    } else {
        const int threads = 256;
        long long blocks_ll = (size + threads - 1) / threads;
        int blocks = (int)(blocks_ll > 1024 ? 1024 : blocks_ll);
        if (blocks < 1) blocks = 1;
        sign_scalar_kernel<<<blocks, threads, 0, stream>>>(output, input, size);
    }
}

