extern "C" void sign_fused_launcher(
    float* output,
    const float* input,
    long long size,
    cudaStream_t stream
);

// torch.sign semantics (IEEE754 sign bit):
//   sign(-0.0) = -0.0, sign(+0.0) = +0.0, sign(NaN) = NaN-with-sign
// A scalar (x>0)-(x<0) expression yields -1.0 for -0.0, which fails the
// tolerance check. The kernel below uses copysignf to reproduce exactly.
