#include <cuda_runtime.h>

// Warp size is 64 on MetaX C500; 104 SMs, 64 KB shared memory per block.
// sign(x) is a pure elementwise memory-bound op, so the goal is to saturate
// DRAM bandwidth: float2 vectorized loads/stores with a fixed ~1024-block
// grid-stride loop (a one-thread-per-element grid reached only ~600 GB/s on
// this device, while this pattern reached ~1300 GB/s of a ~1350 GB/s ceiling).

template<int BLOCK_SIZE>
__global__ void sign_kernel_impl(float* __restrict__ output,
                                 const float* __restrict__ input,
                                 int64_t size) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int64_t stride = (int64_t)blockDim.x * gridDim.x;

    // Vectorized body: consecutive thread pairs handle consecutive float2.
    const int64_t vtid = (int64_t)tid * 2;
    const int64_t vstride = (int64_t)stride * 2;

    int64_t i = vtid;
    const int64_t vec_end = size - (size & 1);
    for (; i < vec_end; i += vstride) {
        float2 v;
        const float2* p = reinterpret_cast<const float2*>(input + i);
        v = *p;
        float2 r;
        r.x = v.x > 0.0f ? 1.0f : (v.x < 0.0f ? -1.0f : 0.0f);
        r.y = v.y > 0.0f ? 1.0f : (v.y < 0.0f ? -1.0f : 0.0f);
        *reinterpret_cast<float2*>(output + i) = r;
    }

    // Tail: odd remaining element (if any).
    if (i < size) {
        float v = input[i];
        output[i] = v > 0.0f ? 1.0f : (v < 0.0f ? -1.0f : 0.0f);
    }
}

extern "C" void sign_kernel_launcher(
    float* output,
    const float* input,
    int64_t size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;  // 4 warps of 64 threads
    // Fixed, coarse grid: enough waves over 104 SMs without oversubscribing
    // with per-thread launch overhead. Grid-stride loop covers any size.
    int blocks = 1024;
    const int64_t max_blocks =
        (size + (int64_t)BLOCK_SIZE * 2 - 1) / ((int64_t)BLOCK_SIZE * 2);
    if ((int64_t)blocks > max_blocks) {
        blocks = (int)max_blocks;
    }
    if (blocks < 1) blocks = 1;

    sign_kernel_impl<BLOCK_SIZE><<<blocks, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

