#include <cuda_runtime.h>

// Hardswish: f(x) = x * clamp(x + 3, 0, 6) / 6
// Memory-bound elementwise op: fusing the add/clamp/mul/div chain into a
// single pass cuts 3 global reads + 2 writes down to 1 read + 1 write.
// Branch-free via fminf/fmaxf so the warp stays divergence-free.

// Vectorized float4 kernel: each thread handles 4 consecutive elements.
// Fixed ~1024-block grid with grid-stride loop keeps the grid coarse
// (measured far better than one-thread-per-element on this device).
template<int BLOCK_SIZE>
__global__ void hardswish_kernel4_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t size4   // number of float4 elements
) {
    const size_t tid = (size_t)blockIdx.x * (size_t)BLOCK_SIZE + (size_t)threadIdx.x;
    const size_t stride = (size_t)BLOCK_SIZE * (size_t)gridDim.x;

    float4* out4 = reinterpret_cast<float4*>(output);
    const float4* in4 = reinterpret_cast<const float4*>(input);

    for (size_t i = tid; i < size4; i += stride) {
        float4 v = in4[i];
        float4 r;
        r.x = v.x * fminf(6.0f, fmaxf(0.0f, v.x + 3.0f)) * 0.16666667163372039794921875f;
        r.y = v.y * fminf(6.0f, fmaxf(0.0f, v.y + 3.0f)) * 0.16666667163372039794921875f;
        r.z = v.z * fminf(6.0f, fmaxf(0.0f, v.z + 3.0f)) * 0.16666667163372039794921875f;
        r.w = v.w * fminf(6.0f, fmaxf(0.0f, v.w + 3.0f)) * 0.16666667163372039794921875f;
        out4[i] = r;
    }
}

// Scalar cleanup kernel for the tail when numel is not a multiple of 4,
// or when the config requests a scalar (float) path.
__global__ void hardswish_kernel1_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t size
) {
    const size_t tid = (size_t)blockIdx.x * (size_t)blockDim.x + (size_t)threadIdx.x;
    const size_t stride = (size_t)blockDim.x * (size_t)gridDim.x;

    for (size_t i = tid; i < size; i += stride) {
        float v = input[i];
        output[i] = v * fminf(6.0f, fmaxf(0.0f, v + 3.0f)) * 0.16666667163372039794921875f;
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void hardswish_launcher(
    float* output,
    const float* input,
    size_t size,
    int config,
    cudaStream_t stream
) {
    if (size == 0) return;

    const size_t size4 = size / 4;
    const size_t tail = size - size4 * 4;

    // Alignment: float4 path requires both pointers 16-byte aligned.
    const bool aligned = (((uintptr_t)output & 0xF) == 0) && (((uintptr_t)input & 0xF) == 0);

    if (aligned && size4 > 0) {
        const int BLOCK = (config == 1) ? 512 : 256;
        // Fixed coarse grid: 1024 blocks * 256 threads, grid-stride loop
        // covers arbitrarily large tensors.
        int blocks = 1024;
        size_t total = (size_t)blocks * (size_t)BLOCK;
        if (total > size4) {
            blocks = (int)((size4 + (size_t)BLOCK - 1) / (size_t)BLOCK);
            if (blocks < 1) blocks = 1;
        }
        if (config == 1) {
            hardswish_kernel4_impl<512><<<blocks, 512, 0, stream>>>(output, input, size4);
        } else {
            hardswish_kernel4_impl<256><<<blocks, 256, 0, stream>>>(output, input, size4);
        }
    } else {
        const int BLOCK = 256;
        size_t s = size4 * 4;  // handle unaligned prefix conservatively
        int blocks = 1024;
        size_t total = (size_t)blocks * (size_t)BLOCK;
        if (total > s) {
            blocks = (int)((s + (size_t)BLOCK - 1) / (size_t)BLOCK);
            if (blocks < 1) blocks = 1;
        }
        hardswish_kernel1_impl<<<blocks, BLOCK, 0, stream>>>(output, input, s);
    }

    if (tail > 0) {
        const int BLOCK = 128;
        int blocks = (int)((tail + BLOCK - 1) / BLOCK);
        if (blocks < 1) blocks = 1;
        if (blocks > 64) blocks = 64;
        hardswish_kernel1_impl<<<blocks, BLOCK, 0, stream>>>(
            output + size4 * 4, input + size4 * 4, tail);
    }
}

