// kernels/hardswish.cu
// Fused Hardswish: out = x * clamp(x + 3, 0, 6) / 6
// Memory-bound elementwise op: a single fused pass replaces 4+ separate
// kernels (add, clamp, mul, div) and their global round trips.
//
// Design (per MACA/C500 notes):
//  - vectorized float4 loads/stores where 16-byte aligned
//  - fixed grid of 104*8 blocks with grid-stride loop (avoids the
//    one-thread-per-element fine-grid trap measured at 338-642 GB/s)
//  - warp size 64, block 256 -> 4 warps per block
#include <cuda_runtime.h>

__device__ __forceinline__ float hardswish_f(float x) {
    float t = x + 3.0f;
    // clamp(t, 0, 6)
    t = fminf(fmaxf(t, 0.0f), 6.0f);
    return x * t * 0.16666667163372039794921875f; // /6
}

// Vectorized body: 4 floats per thread iteration using float4.
__device__ __forceinline__ void vec4_body(float4* __restrict__ o4,
                                          const float4* __restrict__ i4,
                                          size_t count4) {
    if (count4 == 0) return;
    unsigned int tid = blockIdx.x * blockDim.x + threadIdx.x;
    unsigned int stride = blockDim.x * gridDim.x;
    for (size_t i = tid; i < count4; i += stride) {
        float4 v = i4[i];
        float4 r;
        r.x = hardswish_f(v.x);
        r.y = hardswish_f(v.y);
        r.z = hardswish_f(v.z);
        r.w = hardswish_f(v.w);
        o4[i] = r;
    }
}

// Scalar body for the tail (and for non-aligned buffers).
__device__ __forceinline__ void scalar_body(float* __restrict__ o,
                                            const float* __restrict__ i,
                                            size_t n) {
    unsigned int tid = blockIdx.x * blockDim.x + threadIdx.y;
    unsigned int stride = blockDim.x * gridDim.x;
    for (size_t k = tid; k < n; k += stride) {
        o[k] = hardswish_f(i[k]);
    }
}

extern "C" void hardswish_fwd(const float* __restrict__ out,
                              const float* __restrict__ in,
                              size_t n,
                              cudaStream_t stream) {
    if (n == 0) return;

    const int kBlock = 256;
    // Fixed grid sized to fill 104 SMs several times over; grid-stride loop
    // handles any remainder. Keeps launch stable and avoids fine grids.
    const int kGrid = 104 * 8;

    const uintptr_t a_out = reinterpret_cast<uintptr_t>(out);
    const uintptr_t a_in  = reinterpret_cast<uintptr_t>(in);
    const bool aligned16 = ((a_out | a_in) & 0xF) == 0;

    if (aligned16) {
        size_t n4 = n >> 2;                 // full 16-byte groups
        size_t rem = n - (n4 << 2);         // leftover elements
        vec4_body<<<kGrid, kBlock, 0, stream>>>(
            reinterpret_cast<float4*>(out),
            reinterpret_cast<const float4*>(in),
            n4);
        if (rem > 0) {
            scalar_body<<<32, kBlock, 0, stream>>>(
                const_cast<float*>(out + (n4 << 2)),
                in + (n4 << 2),
                rem);
        }
    } else {
        scalar_body<<<kGrid, kBlock, 0, stream>>>(const_cast<float*>(out), in, n);
    }
}

