#include <cuda_runtime.h>

// Hardswish: x * clamp(x + 3, 0, 6)
// Branch-free, single-pass, memory-bound elementwise op.
// Vectorized with float2 loads + fixed 1024-block grid-stride loop:
// measured sweet spot on MetaX C500 (~1300 GB/s vs ~1350 GB/s ceiling).
__device__ __forceinline__ float hardswish_f(float x) {
    float t = x + 3.0f;
    t = fminf(fmaxf(t, 0.0f), 6.0f);
    return x * t;
}

template<int BLOCK_SIZE>
__global__ void hardswish_kernel(float* __restrict__ output,
                                 const float* __restrict__ input,
                                 int size) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Float2 phase: process aligned pairs
    int n2 = (size >> 1);
    int rem = size - (n2 << 1);

    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

    for (int i = tid; i < n2; i += stride) {
        float2 v = in2[i];
        float2 r;
        r.x = hardswish_f(v.x);
        r.y = hardswish_f(v.y);
        out2[i] = r;
    }

    // Tail element
    int tail = (n2 << 1) + (tid % 64);
    if (tid < rem && tail < size) {
        output[tail] = hardswish_f(input[tail]);
    }
}

extern "C" void hardswish_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;      // 4 warps of 64 threads
    const int GRID = 1024;           // fixed grid: ~10 blocks/SM across 104 SMs
    int blocks = (size + BLOCK_SIZE - 1) / BLOCK_SIZE;
    if (blocks > GRID) blocks = GRID;

    hardswish_kernel<BLOCK_SIZE><<<blocks, BLOCK_SIZE, 0, stream>>>(output, input, size);
}

