#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void softshrink_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size,
    float lambd
) {
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;

    // Float2 vectorized grid-stride loop: one pass over memory,
    // branch-free softshrink: x - lambd*sign(x) where |x| > lambd else 0.
    int i = tid * 2;
    const int last = size - 1;
    while (i < last) {
        float2 v = *reinterpret_cast<const float2*>(input + i);
        float2 o;
        float a = v.x, b = v.y;
        float sa = copysignf(lambd, a);
        float sb = copysignf(lambd, b);
        float ca = a - sa;
        float cb = b - sb;
        o.x = (fabsf(a) > lambd) ? ca : 0.0f;
        o.y = (fabsf(b) > lambd) ? cb : 0.0f;
        *reinterpret_cast<float2*>(output + i) = o;
        i += stride * 2;
    }
    if (i == last) {
        float a = input[i];
        float ca = a - copysignf(lambd, a);
        output[i] = (fabsf(a) > lambd) ? ca : 0.0f;
    }
}

extern "C" void softshrink_launcher(
    float* output,
    const float* input,
    int size,
    float lambd,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;
    // Fixed ~1024-block grid-stride loop: too fine a grid (one block per
    // element chunk) measured only ~340-640 GB/s on this device, while a
    // coarse persistent-style grid reaches ~1300 GB/s.
    int grid = 1024;
    int max_grid = (size / 2 + BLOCK_SIZE - 1) / BLOCK_SIZE;
    if (grid > max_grid) grid = max_grid;
    if (grid < 1) grid = 1;

    softshrink_kernel<256><<<grid, BLOCK_SIZE, 0, stream>>>(
        output, input, size, lambd);
}

