// kernels/softshrink.cu
// Fused Softshrink: y = x - lambd if x >  lambd
//                   y = x + lambd if x < -lambd
//                   y = 0         otherwise
//
// Performance design (MetaX C500, warp size 64, 104 SMs):
//   * float2 vectorized loads/stores (2 elements per memory transaction)
//   * grid-stride loop over a FIXED 1024-block grid (104 SMs comfortably
//     saturated, avoids the one-thread-per-element trap measured at ~600 GB/s)
//   * branch-free arithmetic formulation so the memory traffic dominates

#include <cuda_runtime.h>

// Number of blocks launched. Fixed grid: 1024 blocks x 256 threads.
// At 256 threads/block with float2, each iteration touches 512 elements.
#define NUM_BLOCKS 1024
#define BLOCK_THREADS 256

__device__ __forceinline__ float softshrink_scalar(float x, float lambd) {
    // branch-free form: s = (x > 0) ? -lambd : +lambd
    //                   t = x + s  (i.e. x - lambd for positive, x + lambd for negative)
    //                   y = t if |x| > lambd else 0
    float s = copysignf(lambd, -x);        // -lambd when x > 0, +lambd when x < 0
    float t = x + s;
    float a = fabsf(x);
    // mask = 0xFFFFFFFF if a > lambd else 0
    unsigned mask = a > lambd ? 0xFFFFFFFFu : 0u;
    return __int_as_float(__float_as_int(t) & mask);
}

// Scalar fallback for the tail (odd element count, includes the last element)
__global__ void softshrink_tail_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size,
    float lambd)
{
    int64_t tid = (int64_t)blockIdx.x * (int64_t)blockDim.x + (int64_t)threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * (int64_t)gridDim.x;
    for (int64_t i = tid; i < size; i += stride) {
        output[i] = softshrink_scalar(input[i], lambd);
    }
}

__global__ void softshrink_vec2_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size2,      // number of float2 elements (may exceed real count by 1)
    int64_t size_total, // total scalar elements
    float lambd)
{
    const int64_t tid = (int64_t)blockIdx.x * (int64_t)blockDim.x + (int64_t)threadIdx.x;
    const int64_t stride = (int64_t)blockDim.x * (int64_t)gridDim.x;

    float* out2 = output;
    const float2* in2 = reinterpret_cast<const float2*>(input);

    #pragma unroll 1
    for (int64_t v = tid; v < size2; v += stride) {
        // Bounds: this thread's vector covers scalars [2v, 2v+1].
        // Fully inside -> vector path. Partial (last odd element) -> scalar.
        if (2 * v + 1 < size_total) {
            float2 xx = in2[v];
            float2 yy;
            yy.x = softshrink_scalar(xx.x, lambd);
            yy.y = softshrink_scalar(xx.y, lambd);
            reinterpret_cast<float2*>(out2)[v] = yy;
        } else if (2 * v < size_total) {
            // Exactly one element left and it belongs to this vector slot
            out2[2 * v] = softshrink_scalar(in2[2 * v], lambd);
        }
    }
}

extern "C" void softshrink_fwd_launcher(
    float* output,
    const float* input,
    int64_t size,
    float lambd,
    cudaStream_t stream)
{
    if (size <= 0) return;

    // Align check: inputs from torch::empty_like on a contiguous float tensor
    // are 4-byte aligned at minimum; most are 256-byte aligned. We detect
    // 8-byte alignment to decide whether the float2 path is safe.
    const bool out_aligned = ((uintptr_t)output & 0x7ULL) == 0;
    const bool in_aligned  = ((uintptr_t)input  & 0x7ULL) == 0;

    if (out_aligned && in_aligned) {
        // Round UP on the vector count: the loop handles the odd tail scalar
        // via an inner bounds check, so no element is read/written past the end.
        int64_t size2 = (size + 1) / 2;
        softshrink_vec2_kernel<<<NUM_BLOCKS, BLOCK_THREADS, 0, stream>>>(
            output, input, size2, size, lambd);
    } else {
        // Unaligned fallback: scalar grid-stride over a fixed grid.
        softshrink_tail_kernel<<<NUM_BLOCKS, BLOCK_THREADS, 0, stream>>>(
            output, input, size, lambd);
    }
}

