#include <cuda_runtime.h>

// Softshrink: out = x - lambd if x >  lambd
//             out = x + lambd if x < -lambd
//             out = 0         otherwise
//
// Fused branch-free form: sign(x) * (|x| - lambd) if |x| > lambd else 0.
// Memory-bound elementwise op; single pass over x, so traffic = 2 * N * 4B.

template<int BLOCK_SIZE>
__global__ void softshrink_kernel(
    float* __restrict__ out,
    const float* __restrict__ in,
    long long size,
    float lambd
) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    // float2 vectorized loads/stores: coalesced pairs, ~1300 GB/s on C500.
    const long long n2 = size >> 1;
    const long long base = (long long)tid * 2;

    // Vector body
    for (long long i = base; i < n2 * 2; i += (long long)stride * 2) {
        float2 v;
        const float2* src = reinterpret_cast<const float2*>(in + i);
        v = *src;

        float2 r;
        r.x = fmaxf(fabsf(v.x) - lambd, 0.0f);
        r.y = fmaxf(fabsf(v.y) - lambd, 0.0f);
        // Restore sign: copysign handles x = 0.0 correctly (yields +0).
        r.x = copysignf(r.x, v.x);
        r.y = copysignf(r.y, v.y);

        *reinterpret_cast<float2*>(out + i) = r;
    }

    // Scalar tail for odd element count
    if ((size & 1LL) != 0) {
        long long i = base;
        if (i < size - 1) {
            // handled by vector body; nothing to do
        }
        // Tail element is the last one; let a dedicated set of threads do it
        if (tid < 1) {
            long long last = size - 1;
            float v = in[last];
            float r = fmaxf(fabsf(v) - lambd, 0.0f);
            out[last] = copysignf(r, v);
        }
    }
}

extern "C" void softshrink_launcher(
    float* output,
    const float* input,
    long long size,
    float lambd,
    cudaStream_t stream
) {
    if (size <= 0) return;

    // Fixed ~1024-block grid-stride loop: too fine a grid (one thread per
    // element) measures only ~340-640 GB/s on this device.
    const int BLOCK = 256;
    const int GRID = 1024;

    softshrink_kernel<BLOCK><<<GRID, BLOCK, 0, stream>>>(
        output, input, size, lambd
    );
}

