// kernels/hardtanh.cu
// Fused Hardtanh(min=0, max=1) — i.e. clamp(x, 0, 1) — for MetaX C500.
//
// Memory-bound elementwise op on ~805 MB of float32. Strategy:
//  - float4 (16-byte) vectorized loads/stores for coalesced wide access
//  - fixed grid of 1024 blocks, grid-stride loop (avoids the fine-grid
//    trap: one-thread-per-element grids hit only ~340-640 GB/s here)
//  - each thread walks a contiguous 8-element tile per stride iteration
//    (2 x float4) to give the scheduler independent work
//  - clamp compiled to fmin/fmax (branch-free)

#include <cuda_runtime.h>

// Number of float4 elements one thread owns per stride iteration.
#define VEC_PER_THREAD 2

template<int BLOCK_SIZE, int VPT>
__global__ void hardtanh_kernel_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t num_elements
) {
    const int64_t tid = (int64_t)blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int64_t stride = (int64_t)BLOCK_SIZE * gridDim.x;

    // Each thread processes a contiguous tile of VPT*4 floats per pass.
    const int64_t thread_span = (int64_t)VPT * 4;
    const int64_t base = tid * thread_span;

    // Total threads in the grid.
    const int64_t total_threads = stride;

    for (int64_t i = base; i < num_elements; i += total_threads * thread_span) {
        // Load up to VPT float4 vectors, guarding the tail.
        float4 v[VPT];
        bool valid[VPT];

        #pragma unroll
        for (int k = 0; k < VPT; ++k) {
            int64_t off = i + (int64_t)k * 4;
            valid[k] = (off + 3 < num_elements);
            if (valid[k]) {
                v[k] = *reinterpret_cast<const float4*>(input + off);
            } else {
                // Tail: handle remaining scalars one by one.
                for (int r = 0; r < 4; ++r) {
                    int64_t so = off + r;
                    if (so < num_elements) {
                        float val = input[so];
                        val = fminf(fmaxf(val, 0.0f), 1.0f);
                        output[so] = val;
                    }
                }
            }
        }

        // Branch-free clamp on full vectors, then store.
        #pragma unroll
        for (int k = 0; k < VPT; ++k) {
            if (valid[k]) {
                float4 w;
                w.x = fminf(fmaxf(v[k].x, 0.0f), 1.0f);
                w.y = fminf(fmaxf(v[k].y, 0.0f), 1.0f);
                w.z = fminf(fmaxf(v[k].z, 0.0f), 1.0f);
                w.w = fminf(fmaxf(v[k].w, 0.0f), 1.0f);
                *reinterpret_cast<float4*>(output + i + (int64_t)k * 4) = w;
            }
        }
    }
}

// C-interface launcher (no PyTorch dependencies).
extern "C" void hardtanh_launcher(
    float* output,
    const float* input,
    int64_t size,
    cudaStream_t stream
) {
    // Fixed grid of 1024 blocks. With BLOCK_SIZE=256 and VPT=2 this gives
    // 1024*256*8 = ~2.1M elements per stride pass; for 805M elements the
    // grid loops ~380 times, keeping all 104 SMs saturated with a large
    // enough wave per launch.
    const int BLOCK_SIZE = 256;
    const int GRID = 1024;

    if (size <= 0) return;

    // Ensure 16-byte alignment of the base pointers for float4 accesses.
    // PyTorch tensors are at least 256-byte aligned, so this always holds;
    // the scalar tail path covers any non-multiple element count.
    hardtanh_kernel_impl<256, VEC_PER_THREAD>
        <<<GRID, BLOCK_SIZE, 0, stream>>>(output, input, size);
}

