#include <cuda_runtime.h>

// Hardtanh(min_val=-1.0f, max_val=1.0f): out = clamp(x, -1, 1)
//
// Memory-bound elementwise op on a large tensor (64*3*2048*2048 floats).
// Strategy: fixed grid of 1024 blocks, 256 threads, grid-stride loop with
// float2 vectorized loads/stores. Tail is handled with a per-lane predicate
// so no element is ever written twice and no out-of-bounds access occurs.

template<int BLOCK_SIZE>
__global__ void hard_sigmoid_kernel_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size
) {
    int64_t tid = (int64_t)blockIdx.x * (int64_t)BLOCK_SIZE + (int64_t)threadIdx.x;
    const int64_t stride = (int64_t)BLOCK_SIZE * (int64_t)gridDim.x;

    const int64_t v_size = size >> 1;          // number of complete float2 pairs
    const int64_t stride2 = stride << 1;       // stride in elements

    // Vectorized body: process complete float2 pairs only.
    for (int64_t i = tid; i < v_size; i += stride) {
        float2 v;
        const float2* p = reinterpret_cast<const float2*>(input) + i;
        v = *p;  // aligned, coalesced 8-byte load

        float2 r;
        r.x = fminf(fmaxf(v.x, -1.0f), 1.0f);
        r.y = fminf(fmaxf(v.y, -1.0f), 1.0f);

        reinterpret_cast<float2*>(output)[i] = r;
    }

    // Scalar tail: only the exact leftover element, guarded per lane.
    int64_t tail_start = v_size << 1;
    for (int64_t j = tail_start + tid; j < size; j += stride) {
        output[j] = fminf(fmaxf(input[j], -1.0f), 1.0f);
    }
}

extern "C" void hard_sigmoid_kernel_launcher(
    float* output,
    const float* input,
    int64_t size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;
    // Fixed, moderate grid: 1024 blocks covers 256K threads; grid-stride loop
    // handles the rest. Fine-grained one-thread-per-element grids measured
    // 2-4x slower on this device.
    int blocks = 1024;

    // Small inputs: don't oversubscribe.
    int64_t max_blocks = (size + BLOCK_SIZE - 1) / BLOCK_SIZE;
    if ((int64_t)blocks > max_blocks) {
        blocks = (int)max_blocks;
        if (blocks < 1) blocks = 1;
    }

    hard_sigmoid_kernel_impl<BLOCK_SIZE><<<blocks, BLOCK_SIZE, 0, stream>>>(
        output, input, size
