#include <cuda_runtime.h>

// Hardtanh: clamp(x, -1.0, 1.0). Memory-bound elementwise op.
//
// Performance notes for MetaX C500 (warp size 64, 104 SMs):
//  - Fixed grid of blocks with grid-stride loop (no one-thread-per-element
//    grid; a 768K-block grid measured only ~338-642 GB/s here).
//  - Vectorized float2 / float4 loads+stores to approach the ~1350 GB/s
//    copy ceiling.
//  - Treat the flat buffer as float2/float4 elements and handle any trailing
//    scalar tail in the same pass.

template<int BLOCK_SIZE, int VEC>
__global__ void hardtanh_kernel(float* __restrict__ output,
                                const float* __restrict__ input,
                                int64_t numel) {
    const int64_t v_numel = numel / VEC;
    const int tail = numel - v_numel * VEC;  // 0..VEC-1

    // Vector body
    for (int64_t i = (int64_t)blockIdx.x * BLOCK_SIZE + threadIdx.x;
         i < v_numel;
         i += (int64_t)BLOCK_SIZE * gridDim.x) {
        if (VEC == 2) {
            float2 v = reinterpret_cast<const float2*>(input)[i];
            v.x = fminf(fmaxf(v.x, -1.0f), 1.0f);
            v.y = fminf(fmaxf(v.y, -1.0f), 1.0f);
            reinterpret_cast<float2*>(output)[i] = v;
        } else if (VEC == 4) {
            float4 v = reinterpret_cast<const float4*>(input)[i];
            v.x = fminf(fmaxf(v.x, -1.0f), 1.0f);
            v.y = fminf(fmaxf(v.y, -1.0f), 1.0f);
            v.z = fminf(fmaxf(v.z, -1.0f), 1.0f);
            v.w = fminf(fmaxf(v.w, -1.0f), 1.0f);
            reinterpret_cast<float4*>(output)[i] = v;
        }
    }

    // Scalar tail (at most VEC-1 elements), handled by block 0 only
    if (tail > 0 && blockIdx.x == 0) {
        for (int64_t i = v_numel + threadIdx.x; i < numel;
             i += BLOCK_SIZE) {
            float v = input[i];
            output[i] = fminf(fmaxf(v, -1.0f), 1.0f);
        }
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void hardtanh_launcher(
    float* output,
    const float* input,
    int64_t numel,
    int config,
    cudaStream_t stream
) {
    // Fixed grid sized to fill 104 SMs with a couple of waves; grid-stride
    // loop covers arbitrarily large numel.
    const int BLOCK_SIZE = 256;
    const int GRID = 1024;

    // Guard against tiny inputs (avoid zero-block grid).
    int grid = GRID;
    int64_t v_numel = numel / 4;
    int64_t max_needed = (v_numel + BLOCK_SIZE - 1) / BLOCK_SIZE;
    if ((int64_t)grid > max_needed && max_needed > 0) grid = (int)max_needed;
    if (grid < 1) grid = 1;

    switch (config) {
        case 1:  // float2
            hardtanh_kernel<256, 2><<<grid, BLOCK_SIZE, 0, stream>>>(
                output, input, numel);
            break;
        case 0:  // float4 (default)
        default:
            hardtanh_kernel<256, 4><<<grid, BLOCK_SIZE, 0, stream>>>(
                output, input, numel);
            break;
    }
}

