#include <cuda_runtime.h>

// Fused hardtanh: out = clamp(x, -1.0f, 1.0f).
// Single pass over memory: reads N floats, writes N floats.
// Vectorized with float4 loads/stores and a fixed-grid stride loop to keep
// the grid coarse (this device slows badly with one-thread-per-element grids).

template<int BLOCK_SIZE>
__global__ void hardtanh_kernel_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t size
) {
    // Vectorized element index for this thread (each thread handles 4 floats)
    size_t tid = static_cast<size_t>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    const size_t stride = static_cast<size_t>(BLOCK_SIZE) * gridDim.x;
    const size_t n4 = size >> 2;  // number of complete float4 groups

    // Fast path: aligned, complete float4 groups
    if (n4 > 0) {
        float4* out4 = reinterpret_cast<float4*>(output);
        const float4* in4 = reinterpret_cast<const float4*>(input);

        for (size_t i = tid; i < n4; i += stride) {
            float4 v = in4[i];
            float4 r;
            r.x = fminf(fmaxf(v.x, -1.0f), 1.0f);
            r.y = fminf(fmaxf(v.y, -1.0f), 1.0f);
            r.z = fminf(fmaxf(v.z, -1.0f), 1.0f);
            r.w = fminf(fmaxf(v.w, -1.0f), 1.0f);
            out4[i] = r;
        }
    }

    // Tail: remaining scalars (size % 4), handled by the first few threads
    const size_t tail_base = n4 << 2;
    const size_t rem = size - tail_base;
    if (tid < rem) {
        size_t idx = tail_base + tid;
        output[idx] = fminf(fmaxf(input[idx], -1.0f), 1.0f);
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void hardtanh_kernel_launcher(
    float* output,
    const float* input,
    size_t size,
    cudaStream_t stream
) {
    // Threads per block in float4 units; 256 threads/block = 1K floats/block.
    const int BLOCK_SIZE = 256;
    // Fixed coarse grid: ~1024 blocks total keeps waves full on 104 SMs and
    // avoids the fine-granularity trap measured on this device.
    const int GRID = 1024;

    hardtanh_kernel_impl<BLOCK_SIZE><<<GRID, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

