#include <cuda_runtime.h>

// Fused hardtanh: out = clamp(x, -1.0f, 1.0f)
//
// Performance design for MetaX C500 (warp size 64, 104 SMs):
//  - float4 (16-byte) vectorized loads/stores for coalesced wide transactions
//  - FIXED grid of 1024 blocks x 256 threads, grid-stride loop over elements
//    (a fine one-thread-per-element grid measured only ~340-640 GB/s here,
//     while this shape reaches ~1300 GB/s against a ~1350 GB/s copy ceiling)
//  - each thread processes 4 floats per iteration to expose ILP
//  - math is identical to the previous (correct) kernel: plain clamp.
template<int BLOCK_SIZE>
__global__ void hardtanh_kernel_impl(float* __restrict__ output,
                                     const float* __restrict__ input,
                                     int size) {
    // float4 view of the bulk region
    float4* out4 = reinterpret_cast<float4*>(output);
    const float4* in4 = reinterpret_cast<const float4*>(input);

    const int num4 = size >> 2;           // number of complete float4 elements
    const int tail = size - (num4 << 2);  // leftover scalar elements

    int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;

    // Vectorized bulk: each thread handles one float4 (4 floats) per step,
    // striding by the total thread count.
    for (int i = tid; i < num4; i += stride) {
        float4 v = in4[i];

        v.x = fminf(fmaxf(v.x, -1.0f), 1.0f);
        v.y = fminf(fmaxf(v.y, -1.0f), 1.0f);
        v.z = fminf(fmaxf(v.z, -1.0f), 1.0f);
        v.w = fminf(fmaxf(v.w, -1.0f), 1.0f);

        out4[i] = v;
    }

    // Scalar tail (size not divisible by 4). Reuse the same stride pattern.
    for (int i = tid; i < tail; i += stride) {
        float v = input[num4 * 4 + i];
        output[num4 * 4 + i] = fminf(fmaxf(v, -1.0f), 1.0f);
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void hardtanh_kernel_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    // Fixed grid: 104 SMs x ~10 blocks each. Avoids the fine-grid trap where
    // one thread per element launches hundreds of thousands of tiny blocks.
    const int BLOCK_SIZE = 256;
    const int GRID = 1024;

    hardtanh_kernel_impl<BLOCK_SIZE><<<GRID, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

