// Fused hardtanh: out = clamp(x, -1.0f, 1.0f)
// Memory-bound elementwise op: single pass over x, so we vectorize with float2
// and use a fixed-size grid-stride loop (1024 blocks) as recommended for C500.
// Warp size is 64 on this device, so a 256-thread block = 4 warps.

template<int BLOCK_SIZE>
__global__ void hardtanh_kernel_impl(float* __restrict__ output,
                                     const float* __restrict__ input,
                                     int size) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // float2 vectorized path: handles pairs of elements
    int n2 = size >> 1;
    int stride2 = stride >> 1;

    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

    for (int i = tid; i < n2; i += stride2) {
        float2 v = in2[i];
        v.x = fminf(fmaxf(v.x, -1.0f), 1.0f);
        v.y = fminf(fmaxf(v.y, -1.0f), 1.0f);
        out2[i] = v;
    }

    // Tail: odd element count
    if ((size & 1) == 1) {
        for (int i = tid + 2 * n2; i < size; i += stride) {
            output[i] = fminf(fmaxf(input[i], -1.0f), 1.0f);
        }
    }
}

extern "C" void hardtanh_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int blocks = 1024;
    const int threads = 256;

    switch (config) {
        case 1:  // 128 threads, more blocks for finer granularity
            hardtanh_kernel_impl<128><<<blocks * 2, 128, 0, stream>>>(output, input, size);
            break;
        case 2:  // 512 threads
            hardtanh_kernel_impl<512><<<blocks / 2, 512, 0, stream>>>(output, input, size);
            break;
        default: // 256 threads (balanced)
            hardtanh_kernel_impl<256><<<blocks, threads, 0, stream>>>(output, input, size);
            break;
    }
}

