// kernels/hardsigmoid_fused.cu
// Fused hardsigmoid: clamp(x/6 + 0.5, 0, 1)  ==  min(max(x/6+0.5, 0), 1)
//
// Memory-bound elementwise fusion on MetaX C500:
//   - warp size 64, 104 SMs, 64 KB shared mem/block
//   - float2 (64-bit) loads/stores for coalesced 8-byte transactions
//   - fixed ~1024-block grid-stride loop (fine per-element grids measured
//     only ~600 GB/s here; fixed-grid float2 reaches ~1227-1319 GB/s)
//   - branch-free clamp via fminf/fmaxf
#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void hardsigmoid_fused_impl(float* __restrict__ output,
                                       const float* __restrict__ input,
                                       long long size) {
    // float2 vectorized processing: each thread handles 2 elements per step.
    const long long tid = (long long)blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const long long total_threads = (long long)BLOCK_SIZE * gridDim.x;
    const long long v_per_step = total_threads * 2LL;

    // Scalar tail elements (size odd) handled by the first (size - veven) threads.
    const long long veven = size & ~1LL;
    const long long tail = size - veven;

    // Process the vectorized body.
    for (long long base = tid * 2; base < veven; base += v_per_step) {
        float2 v;
        const float2* p = reinterpret_cast<const float2*>(input + base);
        v = *p;  // 8-byte coalesced load

        // hardsigmoid: x/6 + 0.5, clamped to [0, 1]
        const float inv6 = 0.16666667163372039794921875f;  // 1/6 in float
        float a = fmaf(v.x, inv6, 0.5f);
        float b = fmaf(v.y, inv6, 0.5f);
        a = fminf(fmaxf(a, 0.0f), 1.0f);
        b = fminf(fmaxf(b, 0.0f), 1.0f);

        float2 out;
        out.x = a;
        out.y = b;
        *reinterpret_cast<float2*>(output + base) = out;  // 8-byte coalesced store
    }

    // Odd-sized tail (only when size is odd).
    if (tail == 1 && tid == 0) {
        const float inv6 = 0.16666667163372039794921875f;
        float a = fmaf(input[veven], inv6, 0.5f);
        output[veven] = fminf(fmaxf(a, 0.0f), 1.0f);
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void hardsigmoid_fused_launcher(
    float* output,
    const float* input,
    long long size,
    int config,
    cudaStream_t stream
) {
    // Fixed grid sized to fully occupy the 104 SMs without a fine per-element
    // grid. Each block processes BLOCK_SIZE*2 elements per stride iteration.
    if (size <= 0) return;

    const long long nthreads = (size + 1) / 2;  // float2 elements (rounded up)
    int blocks;
    switch (config) {
        case 0: {  // 256 threads/block -> 1024 blocks baseline
            const int BLOCK_SIZE = 256;
            blocks = (int)min(nthreads, 262144LL);  // 1024 blocks * 256 threads
            blocks = (blocks + BLOCK_SIZE - 1) / BLOCK_SIZE;
            if (blocks < 1) blocks = 1;
            if (blocks > 1024) blocks = 1024;
            hardsigmoid_fused_impl<256><<<blocks, BLOCK_SIZE, 0, stream>>>(output, input, size);
            break;
        }
        case 1: {  // 128 threads/block
            const int BLOCK_SIZE = 128;
            blocks = (int)min(nthreads, 131072LL);
            blocks = (blocks + BLOCK_SIZE - 1) / BLOCK_SIZE;
            if (blocks < 1) blocks = 1;
            if (blocks > 2048) blocks = 2048;
            hardsigmoid_fused_impl<128><<<blocks, BLOCK_SIZE, 0, stream>>>(output, input, size);
            break;
        }
        case 2: {  // 512 threads/block
            const int BLOCK_SIZE = 512;
            blocks = (int)min(nthreads, 524288LL);
            blocks = (blocks + BLOCK_SIZE - 1) / BLOCK_SIZE;
            if (blocks < 1) blocks = 1;
            if (blocks > 512) blocks = 512;
            hardsigmoid_fused_impl<512><<<blocks, BLOCK_SIZE, 0, stream>>>(output, input, size);
            break;
        }
        default: {
            const int BLOCK_SIZE = 256;
            blocks = (int)min(nthreads, 262144LL);
            blocks = (blocks + BLOCK_SIZE - 1) / BLOCK_SIZE;
            if (blocks < 1) blocks = 1;
            if (blocks > 1024) blocks = 1024;
            hardsigmoid_fused_impl<256><<<blocks, BLOCK_SIZE, 0, stream>>>(output, input, size);
            break;
        }
    }
}

