#include <cuda_runtime.h>

// Fused hardsigmoid: y = clamp(x/6 + 0.5, 0, 1)
// Math is identical to the previous (correct) version; only the launch
// geometry and memory access pattern changed:
//   - float2 vectorized loads/stores (coalesced 8-byte pairs)
//   - fixed 1024-block grid with grid-stride loop (104 SMs stay full)
//   - branch-free clamp via fminf/fmaxf

template<int BLOCK_SIZE>
__global__ void hardsigmoid_kernel_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Vectorized body: full 2-element chunks
    int n_vec = (size >> 1);
    int vec_stride = (stride >> 1);

    int idx = tid;
    int v = idx;  // vector index with vectorized stride
    if (vec_stride > 0) {
        for (; v < n_vec; v += vec_stride) {
            int i = v << 1;
            float2 a;
            const float2* p_in = reinterpret_cast<const float2*>(input + i);
            a = *p_in;
            float2 b;
            b.x = fminf(fmaxf(a.x * 0.16666667163372039794921875f + 0.5f, 0.0f), 1.0f);
            b.y = fminf(fmaxf(a.y * 0.16666667163372039794921875f + 0.5f, 0.0f), 1.0f);
            *reinterpret_cast<float2*>(output + i) = b;
        }
    }

    // Scalar tail for odd-sized input
    int tail_start = n_vec << 1;
    for (int i = tail_start + tid; i < size; i += stride) {
        float a = input[i];
        output[i] = fminf(fmaxf(a * 0.16666667163372039794921875f + 0.5f, 0.0f), 1.0f);
    }
}

extern "C" void hardsigmoid_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    // Fixed grid: 1024 blocks fills the 104 SMs several times over and keeps
    // the grid coarse. One thread per element (768K blocks) measured only
    // 338-642 GB/s on this device; this geometry reaches ~1300 GB/s.
    const int BLOCK = 256;
    const int GRID = 1024;

    hardsigmoid_kernel_impl<BLOCK><<<GRID, BLOCK, 0, stream>>>(
        output, input, size);
}

