// kernels/hardsigmoid_fused.cu
// Fused hardsigmoid: y = clamp(x/6 + 0.5, 0, 1)
//
// Performance design (MetaX C500, 104 SMs, warp 64):
//   - float4 vectorized loads/stores (16-byte transactions, coalesced)
//   - FIXED grid of ~1024 blocks with grid-stride loop; one-thread-per-element
//     grids (768K blocks) measured only 338-642 GB/s on this device.
//   - Branch-free clamp via fminf/fmaxf (single SFU-ish op, no divergence).
//   - Each thread handles VEC=4 elements per iteration -> effective 32768 lanes.

#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void hardsigmoid_vec4_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size            // number of float elements (multiple of 4 guaranteed by caller)
) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;
    const int nvec = size >> 2;   // size / 4

    float4* out4 = reinterpret_cast<float4*>(output);
    const float4* in4 = reinterpret_cast<const float4*>(input);

    for (int i = tid; i < nvec; i += stride) {
        float4 v = in4[i];

        // hardsigmoid(x) = clamp(x * (1/6) + 0.5, 0.0, 1.0)
        // Branch-free: FMUL, FADD, FMIN, FMAX -- fully memory-bound.
        v.x = fminf(fmaxf(v.x * 0.16666667163372039794921875f + 0.5f, 0.0f), 1.0f);
        v.y = fminf(fmaxf(v.y * 0.16666667163372039794921875f + 0.5f, 0.0f), 1.0f);
        v.z = fminf(fmaxf(v.z * 0.16666667163372039794921875f + 0.5f, 0.0f), 1.0f);
        v.w = fminf(fmaxf(v.w * 0.16666667163372039794921875f + 0.5f, 0.0f), 1.0f);

        out4[i] = v;
    }
}

// Scalar tail kernel for sizes not divisible by 4 (or small sizes).
__global__ void hardsigmoid_scalar_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;
    for (int i = tid; i < size; i += stride) {
        float v = input[i];
        output[i] = fminf(fmaxf(v * 0.16666667163372039794921875f + 0.5f, 0.0f), 1.0f);
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void hardsigmoid_fused_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    // Fixed grid sized to fill 104 SMs with several waves; grid-stride loop
    // handles the tail. Config selects block size / occupancy flavor.
    int block_size;
    int blocks;

    switch (config) {
        case 0:  // primary: 256 threads x 1024 blocks
            block_size = 256;
            blocks = 1024;
            break;
        case 1:  // 128 threads, more blocks
            block_size = 128;
            blocks = 2048;
            break;
        case 2:  // 512 threads, fewer blocks
            block_size = 512;
            blocks = 512;
            break;
        case 3:  // 64 threads (one warp), many blocks
            block_size = 64;
            blocks = 4096;
            break;
        default:
            block_size = 256;
            blocks = 1024;
            break;
    }

    // For very small problems, shrink the grid to avoid useless launches.
    int nvec = size >> 2;
    if (nvec > 0 && nvec < blocks * block_size) {
        int need = (nvec + block_size - 1) / block_size;
        if (need < blocks) blocks = need;
        if (blocks < 1) blocks = 1;
    }

    if ((size & 3) == 0 && nvec > 0) {
        if (block_size == 128) {
            hardsigmoid_vec4_kernel<128><<<blocks, 128, 0, stream>>>(output, input, size);
        } else if (block_size == 512) {
            hardsigmoid_vec4_kernel<512><<<blocks, 512, 0, stream>>>(output, input, size);
        } else if (block_size == 64) {
            hardsigmoid_vec4_kernel<64><<<blocks, 64, 0, stream>>>(output, input, size);
        } else {
            hardsigmoid_vec4_kernel<256><<<blocks, 256, 0, stream>>>(output, input, size);
        }
    } else {
        // Non-vectorizable path (size not multiple of 4): scalar grid-stride.
        int sblocks = (size + 255) / 256;
        if (sblocks > 1024) sblocks = 1024;
        hardsigmoid_scalar_kernel<<<sblocks, 256, 0, stream>>>(output, input, size);
    }
}

