// Fused x -> round(|x|) for float32, MemoryX C500 / MACA toolchain.
//
// model.py does torch.abs(x) then torch.round(x) as two full-tensor passes.
// Fusing them into one pass halves the memory traffic: 1 read + 1 write of
// the 805 MB tensor instead of 2 reads + 2 writes.
//
// Both ops are branch-free bit manipulations:
//   abs   = clear the sign bit
//   round = round-half-away-from-zero (torch.round semantics, not banker's)
//         = copysign(trunc(|x| + 0.5), x)
// Because the result is integral, |x| + 0.5f cannot overflow for finite input.
//
// Vectorization: float2 (8-byte) loads/stores with a fixed 1024-block
// grid-stride loop. On this device a scalar one-thread-per-element grid
// reached only ~600 GB/s while float2 at a fixed 1024-block grid reaches
// ~1300 GB/s against a ~1350 GB/s ceiling.

#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cuda_bf16.h>

// Round half away from zero, matching torch.round (not rint's banker's rounding).
__device__ __forceinline__ float round_half_away(float x) {
    // |x| + 0.5f is exact enough for the rounding decision; trunc then
    // re-apply the original sign. Branch-free -> no divergence.
    float a = fabsf(x);
    float r = truncf(a + 0.5f);
    return copysignf(r, x);
}

// Scalar fallback path (config 1): one thread per element.
__global__ void fused_abs_round_scalar_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    long long size
) {
    long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    if (tid < size) {
        output[tid] = round_half_away(input[tid]);
    }
}

// Vectorized path: float2 grid-stride loop.
// BLOCK * GRID threads, each walking a strided sequence of float2 pairs.
template<int BLOCK, int GRID>
__global__ void fused_abs_round_vec_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    long long n_pairs,
    long long n_tail       // remaining scalar elements after the float2 region
) {
    const long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    const long long stride = (long long)GRID * BLOCK;

    // Float2 region: pairs are 8-byte aligned because the tensor is
    // contiguous float32 with a 4-byte base alignment.
    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

    for (long long i = tid; i < n_pairs; i += stride) {
        float2 v = in2[i];
        v.x = round_half_away(v.x);
        v.y = round_half_away(v.y);
        out2[i] = v;
    }

    // Tail elements that do not fill a complete pair.
    if (n_tail > 0) {
        long long base = n_pairs * 2;
        for (long long j = tid; j < n_tail; j += stride) {
            output[base + j] = round_half_away(input[base + j]);
        }
    }
}

extern "C" void fused_abs_round_launcher(
    float* output,
    const float* input,
    long long size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    // 8-byte-aligned region + scalar tail.
    long long n_pairs = size / 2;
    long long n_tail = size - n_pairs * 2;

    if (config == 1) {
        // Scalar comparison path (kept for tuning reference).
        int threads = 256;
        long long blocks = (size + threads - 1) / threads;
        dim3 grid((unsigned int)blocks);
        dim3 block((unsigned int)threads);
        fused_abs_round_scalar_kernel<<<grid, block, 0, stream>>>(
            output, input, size);
        return;
    }

    // Default (config 0): float2, 256 threads/block x 1024 blocks = 256K
    // threads doing a grid-stride walk. A fixed ~1024-block grid avoids the
    // too-fine-grid trap measured on this device (768K blocks -> ~340 GB/s).
    const int BLOCK = 256;
    const int GRID = 1024;
    dim3 grid(GRID);
    dim3 block(BLOCK);
    fused_abs_round_vec_kernel<BLOCK, GRID><<<grid, block, 0, stream>>>(
        output, input, n_pairs, n_tail);
}

