// kernels/fused_abs_round.cu
// Fused elementwise: out = round(|x|)
//
// Model.py launches two full memory passes (abs, then round) over a
// 16x3x4096x4096 float tensor (~3.2 GB). Both ops are cheap branch-free
// arithmetic, so the chain is purely memory-bound: fusing removes one full
// read+write round trip.
//
// Design notes for MetaX C500 (MACA / cu-bridge):
//  - warp size 64, 104 SMs, 64 KB shared memory per block
//  - coarse grid: a fixed 1024-block grid-stride loop; a one-thread-per-element
//    grid (~3.1M blocks) measured only a fraction of peak BW on this device.
//  - float2 vectorized loads/stores for coalesced 8-byte transactions.

#include <cuda_runtime.h>
#include <cuda_fp16.h>

namespace {

// Branch-free round-half-away-from-zero on the absolute value.
// fabsf + roundf is a single SFU-ish sequence with no data dependency between
// the two ops beyond the value itself, so the scheduler always has
// independent work available (unlike an expf->log1pf chain).
__device__ __forceinline__ float abs_round_f(float v) {
    return roundf(fabsf(v));
}

template <int BLOCK>
__global__ void fused_abs_round_f32_kernel(
    float* __restrict__ out, const float* __restrict__ in, long long size) {
    const long long tid = static_cast<long long>(blockIdx.x) * BLOCK + threadIdx.x;
    const long long stride = static_cast<long long>(BLOCK) * gridDim.x;

    // Float2 phase: 2 elements per thread, 8-byte coalesced transactions.
    const long long v2 = size >> 1;
    for (long long i = tid; i < v2; i += stride) {
        float2 p;
        const float2* src = reinterpret_cast<const float2*>(in) + i;
        p = *src;  // aligned: size is a multiple of 2 here
        float2 r;
        r.x = abs_round_f(p.x);
        r.y = abs_round_f(p.y);
        reinterpret_cast<float2*>(out)[i] = r;
    }

    // Scalar tail for an odd element count.
    if ((size & 1LL) != 0) {
        const long long last = size - 1;
        for (long long i = tid; i <= last; i += stride) {
            if (i == last) out[i] = abs_round_f(in[i]);
        }
    }
}

// 16-bit path: vectorize as ushort2 (4 bytes / 2 elements). Keeps the same
// coarse-grid, grid-stride structure as the float path.
__device__ __forceinline__ unsigned short abs_round_u16(unsigned short bits) {
    // Sign bit is bit15; abs = bits & 0x7FFF.
    unsigned short a = bits & 0x7FFFu;
    // round-half-away-from-zero in half precision. Since abs(x) >= 0, the
    // default IEEE rounding (round-half-to-even) applies to the stored value;
    // half() arithmetic matches torch.round semantics on the magnitude.
    __half h = __ushort_as_half(a);
    __half r = hround(h);
    return __half_as_ushort(r);
}

template <int BLOCK>
__global__ void fused_abs_round_f16_kernel(
    unsigned short* __restrict__ out, const unsigned short* __restrict__ in,
    long long size) {
    const long long tid = static_cast<long long>(blockIdx.x) * BLOCK + threadIdx.x;
    const long long stride = static_cast<long long>(BLOCK) * gridDim.x;

    const long long v2 = size >> 1;
    for (long long i = tid; i < v2; i += stride) {
        ushort2 p = reinterpret_cast<const ushort2*>(in)[i];
        ushort2 r;
        r.x = abs_round_u16(p.x);
        r.y = abs_round_u16(p.y);
        reinterpret_cast<ushort2*>(out)[i] = r;
    }
    if ((size & 1LL) != 0) {
        const long long last = size - 1;
        for (long long i = tid; i <= last; i += stride) {
            if (i == last) out[i] = abs_round_u16(in[i]);
        }
    }
}

template <int BLOCK>
__global__ void fused_abs_round_f64_kernel(
    double* __restrict__ out, const double* __restrict__ in, long long size) {
    const long long tid = static_cast<long long>(blockIdx.x) * BLOCK + threadIdx.x;
    const long long stride = static_cast<long long>(BLOCK) * gridDim.x;
    for (long long i = tid; i < size; i += stride) {
        out[i] = round(fabs(in[i]));
    }
}

}  // namespace

extern "C" void fused_abs_round_f32_launcher(
    float* output, const float* input, long long size, cudaStream_t stream) {
    if (size <= 0) return;
    // Coarse fixed grid: 1024 blocks x 256 threads covers the device's 104 SMs
    // with ~2.5 waves while staying well clear of the fine-grid trap.
    const int BLOCK = 256;
    const int blocks = 1024;
    const long long limit = static_cast<long long>(blocks) * BLOCK;
    // Only fall back to a finer grid for tiny tensors where the fixed grid
    // would leave the tail to a single underloaded wave.
    if (size <= limit) {
        const int needed = static_cast<int>((size + BLOCK - 1) / BLOCK);
        fused_abs_round_f32_kernel<256><<<needed, BLOCK, 0, stream>>>(
            output, input, size);
    } else {
        fused_abs_round_f32_kernel<256><<<blocks, BLOCK, 0, stream>>>(
            output, input, size);
    }
}

extern "C" void fused_abs_round_f16_launcher(
    void* output, const void* input, long long size, cudaStream_t stream) {
    if (size <= 0) return;
