    const int blocks = 1024;
    const long long limit = static_cast<long long>(blocks) * BLOCK;
    auto out = reinterpret_cast<unsigned short*>(output);
    auto in = reinterpret_cast<const unsigned short*>(input);
    if (size <= limit) {
        const int needed = static_cast<int>((size + BLOCK - 1) / BLOCK);
        fused_abs_round_f16_kernel<256><<<needed, BLOCK, 0, stream>>>(
            out, in, size);
    } else {
        fused_abs_round_f16_kernel<256><<<blocks, BLOCK, 0, stream>>>(
            out, in, size);
    }
}

extern "C" void fused_abs_round_f64_launcher(
    double* output, const double* input, long long size, cudaStream_t stream) {
    if (size <= 0) return;
    const int BLOCK = 256;
    const int blocks = 1024;
    const long long limit = static_cast<long long>(blocks) * BLOCK;
    if (size <= limit) {
        const int needed = static_cast<int>((size + BLOCK - 1) / BLOCK);
        fused_abs_round_f64_kernel<256><<<needed, BLOCK, 0, stream>>>(
            output, input, size);
    } else {
        fused_abs_round_f64_kernel<256><<<blocks, BLOCK, 0, stream>>>(
            output, input, size);
    }
