#include <cuda_runtime.h>
#include <math_constants.h>

// Fused cat(dim=1) + cos for the shape (B, C, H, W) case where the concat is
// along dim 1: out[:, 0:C1] = cos(t1), out[:, C1:C1+C2] = cos(t2).
// Layout: out row r maps to t1 row r for the first C1 slices and t2 row r for
// the next C2 slices. We process each tensor with its own contiguous tidy
// mapping (row id = block offset) so loads stay perfectly coalesced, and the
// two tensors are interleaved per grid chunk so both streams run concurrently.

template <int BLOCK>
__global__ void fused_cat_cos_impl(
    float* __restrict__ out,
    const float* __restrict__ t1,
    const float* __restrict__ t2,
    long long total1,          // numel of tensor1
    long long total2,          // numel of tensor2
    long long row_elems1,      // numel per row of tensor1
    long long row_elems2,      // numel per row of tensor2
    long long row_elems_out,   // numel per row of output (= row_elems1 + row_elems2)
    long long n_rows)          // batch * height * width (outer dims)
{
    const int tid = blockIdx.x * BLOCK + threadIdx.x;
    const long long stride = (long long)BLOCK * gridDim.x;
    const int lane = threadIdx.x & 63;
    const int warp = threadIdx.x >> 6;
    const int warps = BLOCK >> 6;

    // Each row of t1/t2 is handled by a contiguous group of threads; the grid
    // maps over (row, offset) pairs. Use a flat per-tensor index and derive the
    // row from it, which keeps both accesses coalesced within a tensor.

    // ---- Tensor 1 region ----
    for (long long idx = tid; idx < total1; idx += stride) {
        float v;
        // read via float4 when the sub-warp group is 4-aligned within the row
        // Simplest robust path: scalar load (coalesced) - compiler issues LSU
        // per warp; traffic-bound regime hides latency fully.
        v = t1[idx];
        out[idx] = cosf(v);
    }

    // ---- Tensor 2 region ----
    // Output offset for tensor2 data: same row, column offset row_elems1.
    // Compute out position from idx2 to stay coalesced on both sides.
    for (long long idx2 = tid; idx2 < total2; idx2 += stride) {
        float v = t2[idx2];
        long long row = idx2 / row_elems2;
        long long col = idx2 - row * row_elems2;
        out[row * row_elems_out + row_elems1 + col] = cosf(v);
    }
}

// Vectorized variant: each thread handles 4 consecutive floats via float4.
// Requires row sizes divisible by 4 (true for this task: 8*256*256 etc.), and
// is only used when the runtime check passes.
template <int BLOCK>
__global__ void fused_cat_cos_vec4_impl(
    float* __restrict__ out,
    const float* __restrict__ t1,
    const float* __restrict__ t2,
    long long n4_1,           // total1 / 4
    long long n4_2,           // total2 / 4
    long long row_elems1,     // per-row elems, tensor1
    long long row_elems2,     // per-row elems, tensor2
    long long row_elems_out,  // per-row elems, output
    long long row4_1,         // row_elems1 / 4
    long long row4_2          // row_elems2 / 4
)
{
    const long long tid = (long long)blockIdx.x * BLOCK + threadIdx.x;
    const long long stride = (long long)BLOCK * gridDim.x;

    // Tensor 1: identical layout in out (offset 0).
    for (long long i = tid; i < n4_1; i += stride) {
        float4 v = *reinterpret_cast<const float4*>(t1 + (i << 2));
        float4 r;
        r.x = cosf(v.x);
        r.y = cosf(v.y);
        r.z = cosf(v.z);
        r.w = cosf(v.w);
        *reinterpret_cast<float4*>(out + (i << 2)) = r;
    }

    // Tensor 2: out row = row, col = row_elems1 + col_in_t2.
    for (long long i = tid; i < n4_2; i += stride) {
        float4 v = *reinterpret_cast<const float4*>(t2 + (i << 2));
        long long row = i / row4_2;
        long long col4 = i - row * row4_2;
        float4 r;
        r.x = cosf(v.x);
        r.y = cosf(v.y);
        r.z = cosf(v.z);
        r.w = cosf(v.w);
        *reinterpret_cast<float4*>(out + row * row_elems_out + row_elems1 + (col4 << 2)) = r;
    }
}

extern "C" void fused_cat_cos_launcher(
    float* out,
    const float* t1,
    const float* t2,
    long long total1,
    long long total2,
    long long row_elems1,
    long long row_elems2,
    long long row_elems_out,
    long long n_rows,
    cudaStream_t stream
)
{
    const int BLOCK = 256;
    // Fixed persistent grid: 104 SMs * 8 blocks = 832 blocks covers the device
    // without the fine-grid trap measured on this host.
    const int GRID = 832;

    bool ok4 = (row_elems1 % 4 == 0) && (row_elems2 % 4 == 0) &&
               (row_elems_out % 4 == 0) &&
               (((uintptr_t)t1 & 15) == 0) && (((uintptr_t)t2 & 15) == 0) &&
               (((uintptr_t)out & 15) == 0);

    if (ok4) {
        fused_cat_cos_vec4_impl<BLOCK><<<GRID, BLOCK, 0, stream>>>(
            out, t1, t2,
            total1 >> 2, total2 >> 2,
            row_elems1, row_elems2, row_elems_out,
            row_elems1 >> 2, row_elems2 >> 2);
    } else {
        fused_cat_cos_impl<BLOCK><<<GRID, BLOCK, 0, stream>>>(
            out, t1, t2, total1, total2,
            row_elems1, row_elems2, row_elems_out, n_rows);
    }
}

