// kernels/fused_cat_cos.cu
// Fused concat (flatten of two tensors) + elementwise cos.
// Reads 2*N floats, writes 2*N floats, one kernel launch instead of three.
#include <cuda_runtime.h>

template<int BLOCK>
__global__ void fused_cat_cos_kernel(
    const float* __restrict__ a,
    const float* __restrict__ b,
    float* __restrict__ out,
    const long long a_elems,
    const long long total_elems)
{
    const long long tid = (long long)blockIdx.x * BLOCK + threadIdx.x;
    const long long stride = (long long)BLOCK * gridDim.x;

    for (long long i = tid; i < total_elems; i += stride) {
        const float v = (i < a_elems) ? a[i] : b[i - a_elems];
        out[i] = cosf(v);
    }
}

extern "C" void fused_cat_cos_launcher(
    const float* __restrict__ a,
    const float* __restrict__ b,
    float* __restrict__ out,
    long long a_elems,
    long long total_elems,
    cudaStream_t stream)
{
    const int BLOCK = 256;
    long long blocks = (total_elems + BLOCK - 1) / BLOCK;
    // Cap the grid: persistent-style grid-stride loop keeps enough waves on
    // all 104 SMs without a launch geometry that is finer than one block.
    const long long max_blocks = 1024;
    if (blocks > max_blocks) blocks = max_blocks;
    if (blocks < 1) blocks = 1;

    fused_cat_cos_kernel<256><<<blocks, BLOCK, 0, stream>>>(
        a, b, out, a_elems, total_elems);
}

