    if (t2.dtype() != torch::kFloat32) t2 = t2.to(torch::kFloat32);

    // Normalize contiguity so pointer arithmetic is linear
    if (!t1.is_contiguous()) t1 = t1.contiguous();
    if (!t2.is_contiguous()) t2 = t2.contiguous();

