#include <cuda_runtime.h>

// Fused torch.stack([x1, x2]) along a new leading dimension.
// Writes out[0,*] = x1, out[1,*] = x2 in a single kernel pass, so the two
// source tensors are read exactly once and the output written once.
//
// Design notes for MetaX C500 (warp size 64, 104 SMs):
//  - float2 vectorized loads/stores to approach the ~1.3 TB/s copy ceiling.
//  - fixed 1024-block grid-stride loop (coarse grid) to avoid the fine-grid
//    performance trap observed with one-thread-per-element kernels.
//  - each thread handles a contiguous pair chunk, interleaving the two reads
//    and the two writes to keep the memory pipeline saturated.

__global__ void stack_pair_kernel(
    const float2* __restrict__ x1,
    const float2* __restrict__ x2,
    float2* __restrict__ out0,
    float2* __restrict__ out1,
    size_t npairs)
{
    const size_t stride = (size_t)blockDim.x * gridDim.x;
    size_t tid = (size_t)blockIdx.x * blockDim.x + threadIdx.x;

    for (; tid < npairs; tid += stride) {
        float2 a = x1[tid];
        float2 b = x2[tid];
        out0[tid] = a;
        out1[tid] = b;
    }
}

extern "C" void stack_pair_launcher(
    const float* x1,
    const float* x2,
    float* out,
    size_t n,
    cudaStream_t stream
) {
    const size_t npairs = (n + 1) / 2;
    const int threads = 256;                 // 4 warps of 64 lanes
    const int max_blocks = 1024;
    int blocks = (int)((npairs + threads - 1) / threads);
    if (blocks > max_blocks) blocks = max_blocks;
    if (blocks < 1) blocks = 1;

    stack_pair_kernel<<<blocks, threads, 0, stream>>>(
        reinterpret_cast<const float2*>(x1),
        reinterpret_cast<const float2*>(x2),
        reinterpret_cast<float2*>(out),
        reinterpret_cast<float2*>(out) + npairs,
        npairs
    );
}

