#include <cuda_runtime.h>

// Fused torch.stack([x1, x2], dim=0) for 4D float tensors.
// One pass: out[i, 0, ...] = x1[i, ...], out[i, 1, ...] = x2[i, ...]
//
// Layout: out is (2, B, H, W) contiguous; each (b) slab holds
// [x1_b (pair_stride floats), x2_b (pair_stride floats)].
//
// Strategy: float4 vectorized loads/stores, grid-stride loop over a fixed
// 1024-block grid. Warp size is 64 on this device -> 64 threads/warp,
// 16 warps/block. Each thread handles 4 elements per iteration (one float4).

template<int BLOCK_SIZE, int VEC>
__global__ void fused_stack_kernel(
    float* __restrict__ output,
    const float* __restrict__ input1,
    const float* __restrict__ input2,
    int total_pairs,          // floats per input tensor (B*H*W)
    int pair_stride           // floats per batch slab (H*W)
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Iterate over vectorized units covering both source tensors.
    int nv = total_pairs / VEC;
    int remaining = total_pairs - nv * VEC;

    for (int v = tid; v < nv; v += stride) {
        int gi = v * VEC;                 // index into flat input
        int b = gi / pair_stride;         // batch slab
        int off = gi - b * pair_stride;   // offset inside batch slab

        float4 a = *reinterpret_cast<const float4*>(input1 + gi);
        float4 b2 = *reinterpret_cast<const float4*>(input2 + gi);

        float4 o0, o1;
        o0.x = a.x; o0.y = a.y; o0.z = a.z; o0.w = a.w;
        o1.x = b2.x; o1.y = b2.y; o1.z = b2.z; o1.w = b2.w;

        *reinterpret_cast<float4*>(output + b * (2 * pair_stride) + off) = o0;
        *reinterpret_cast<float4*>(output + b * (2 * pair_stride) + off + pair_stride) = o1;
    }

    // Scalar tail
    if (remaining > 0) {
        for (int i = nv * VEC + tid; i < total_pairs; i += stride) {
            int b = i / pair_stride;
            int off = i - b * pair_stride;
            output[b * (2 * pair_stride) + off] = input1[i];
            output[b * (2 * pair_stride) + off + pair_stride] = input2[i];
        }
    }
}

extern "C" void fused_stack_launcher(
    float* output,
    const float* input1,
    const float* input2,
    int total_pairs,
    int pair_stride,
    cudaStream_t stream
) {
    const int BLOCK = 256;          // 4 warps of 64 threads
    const int VEC = 4;
    // Fixed grid: enough blocks to saturate 104 SMs with several blocks each,
    // grid-stride loop handles the rest. 1024 blocks * 256 threads.
    const int GRID = 1024;

    fused_stack_kernel<BLOCK, VEC><<<GRID, BLOCK, 0, stream>>>(
        output, input1, input2, total_pairs, pair_stride);
}

