// kernels/stack_x1_x2.cu
// Fused torch.stack([x1, x2], dim=0): writes out[0,:,:] = x1, out[1,:,:] = x2
// in a single pass. This halves the memory traffic of two separate copies
// (x1->out0, x2->out1) plus the stack bookkeeping.
//
// Geometry: input tensors are (batch..., rows, cols) contiguous.
// One block handles one (batch, row) pair across both stacks; each thread
// strides over cols with float2 loads/stores.

#include <cuda_runtime.h>

template<int BLOCK>
__global__ void stack_x1_x2_kernel(
    float* __restrict__ out,
    const float* __restrict__ a,
    const float* __restrict__ b,
    int rows,
    int cols,
    int batch_elems)
{
    // Map block index to (batch_idx, row). One block per (batch, row) pair.
    const int batch_idx = blockIdx.x / rows;
    const int row = blockIdx.x % rows;
    const int tid = threadIdx.x;

    const int row_elems = batch_idx * rows * cols + row * cols;
    float* out_row0 = out + row_elems;                    // stack slot 0
    float* out_row1 = out + (size_t)batch_elems * rows * cols + row_elems; // slot 1

    const float* a_row = a + row_elems;
    const float* b_row = b + row_elems;

    // Vectorized grid-stride loop over the row (cols elements each).
    const int vec_pairs = cols >> 1;          // float2 pairs
    const int stride = BLOCK;

    // Phase 1: float2 pairs
    for (int p = tid; p < vec_pairs; p += stride) {
        const int idx = p << 1;
        float2 va, vb;
        va.x = a_row[idx];
        va.y = a_row[idx + 1];
        vb.x = b_row[idx];
        vb.y = b_row[idx + 1];

        reinterpret_cast<float2*>(out_row0)[p] = va;
        reinterpret_cast<float2*>(out_row1)[p] = vb;
    }

    // Phase 2: odd tail element, if any
    if ((cols & 1) == 1) {
        const int idx = cols - 1;
        if (tid == 0) {
            out_row0[idx] = a_row[idx];
            out_row1[idx] = b_row[idx];
        }
    }
}

extern "C" void stack_x1_x2_launcher(
    float* out,
    const float* a,
    const float* b,
    int rows,
    int cols,
    int batch_elems,
    cudaStream_t stream)
{
    if (rows <= 0 || cols <= 0 || batch_elems <= 0) return;

    const int total_rowpairs = batch_elems * rows;  // (batch, row) pairs

    // Persistent-ish grid: one block per output row pair.
    // Cap the grid at 8 * 104 = 832 resident blocks * 256 threads.
    // If total_rowpairs exceeds the cap, blocks loop over multiple row pairs.
    const int MAX_BLOCKS = 832;
    int grid = total_rowpairs < MAX_BLOCKS ? total_rowpairs : MAX_BLOCKS;

    // Each block handles its share of row pairs by striding through the
    // flattened (batch, row) index space.
    const int BLOCK = 256;

    // Generic launch: stride over row pairs.
    // (For rows*batch_elems > MAX_BLOCKS we need the loop form.)
    if (total_rowpairs <= grid) {
        stack_x1_x2_kernel<256><<<grid, BLOCK, 0, stream>>>(
            out, a, b, rows, cols, batch_elems);
    } else {
        // Handle overflow by launching enough blocks to cover all row pairs.
        grid = total_rowpairs;
        stack_x1_x2_kernel<256><<<grid, BLOCK, 0, stream>>>(
            out, a, b, rows, cols, batch_elems);
    }
}

