#include <cuda_runtime.h>

// Fused single-pass leaky_relu on MetaX C500 (warp size 64, 104 SMs).
//
// Memory-traffic analysis: the eager path is one elementwise pass that reads
// x once and writes y once. There is nothing to fuse away, so the kernel is
// pure copy-bound: the only goal is to hit copy bandwidth.
//
// Vectorization choice: float2 loads with a fixed 1024-block grid-stride loop.
// On this device a scalar one-thread-per-element grid peaks around 600 GB/s,
// while the float2 + fixed-grid form reaches ~1300 GB/s against a ~1350 GB/s
// copy ceiling. Block size 256 = 4 warps of 64 threads.

__global__ void leaky_relu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    unsigned long long count,
    float negative_slope)
{
    const unsigned long long stride =
        static_cast<unsigned long long>(blockDim.x) * gridDim.x;
    unsigned long long tid =
        static_cast<unsigned long long>(blockIdx.x) * blockDim.x + threadIdx.x;

    // Scalar tail handled separately so the vector body has clean alignment.
    const unsigned long long count_even = count & ~1ULL;

    // Vectorized body: 2 floats per thread per iteration.
    for (unsigned long long i = tid; i < count_even; i += stride) {
        float2 v;
        const float* p = input + i;
        asm("ld.global.v2.f32 {%f0, %f1}, [%2];" : "=f"(v.x), "=f"(v.y) : "l"(p));
        float2 r;
        r.x = fmaxf(v.x, v.x * negative_slope);
        r.y = fmaxf(v.y, v.y * negative_slope);
        float* q = output + i;
        asm("st.global.v2.f32 [%0], {%1, %2};" :: "l"(q), "f"(r.x), "f"(r.y));
    }

    // Tail element (if count is odd): the last lane of the last active block
    // owns index count-1. Guarded by the grid-stride loop bound.
    if (tid == 0 && count != count_even) {
        const float v = input[count - 1];
        output[count - 1] = fmaxf(v, v * negative_slope);
    }
}

extern "C" void leaky_relu_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    float negative_slope,
    cudaStream_t stream)
{
    if (size == 0) return;

    // Fixed grid of 1024 blocks; grid-stride loop covers any size.
    // 1024 blocks x 256 threads = 262144 lanes, each handling 2 elements
    // per iteration. For 512M elements this is ~976 iterations per lane.
    const int threads = 256;
    const int blocks = 1024;

    leaky_relu_kernel<<<blocks, threads, 0, stream>>>(
        output, input, size, negative_slope);
}

