// kernels/leaky_relu.cu
// Fused single-pass leaky_relu: out = x > 0 ? x : negative_slope * x
// Memory-bound elementwise op. Optimized for MetaX C500 (warp size 64,
// 104 SMs, 64 KB shared memory per block):
//   - float2 vectorized loads/stores (coalesced 8-byte granularity)
//   - fixed 1024-block grid-stride loop (avoids the fine-grid trap)
//   - predicated branch-free select to keep the SFU-free arithmetic cheap
#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void leaky_relu_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    // float2 vectorization: each thread handles pairs of elements
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    const float negative_slope = 0.01f;

    int aligned = size & ~1;  // largest even count <= size
    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

    // Vectorized body
    for (int i = tid; i < (aligned >> 1); i += stride) {
        float2 v = in2[i];
        float2 r;
        r.x = fmaxf(v.x, negative_slope * v.x);
        r.y = fmaxf(v.y, negative_slope * v.y);
        out2[i] = r;
    }

    // Scalar tail for odd element (if any)
    if (aligned < size) {
        int last = size - 1;
        // Let thread 0 of the last-used block handle it; simplest is a
        // dedicated scalar pass guarded by tid == 0.
        if (tid == 0) {
            float v = input[last];
            output[last] = fmaxf(v, negative_slope * v);
        }
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void leaky_relu_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;          // 4 warps of 64 threads
    // Fixed grid of 1024 CTAs -> 256K threads, grid-stride loop for the rest.
    // On C500 the pool of 104 SMs with ~16 blocks/SM occupancy means ~1024
    // blocks saturates the device without the fine-grid launch penalty.
    int grid = 1024;
    // Each block must at least cover the data when size is small.
    int need = (size + 1 + BLOCK_SIZE - 1) / BLOCK_SIZE;  // ceil(size/2 / BLOCK)
    int blocks = need < grid ? need : grid;
    if (blocks < 1) blocks = 1;

    leaky_relu_impl<256><<<blocks, BLOCK_SIZE, 0, stream>>>(output, input, size);
}

