// kernels/fused_stack.cu
// Fused implementation of torch.stack([x, y], dim=0) followed by Identity.
//
// Reference work = two full-tensor reads + one 2x-sized write (here 2 x 167.8M
// floats in, 335.5M floats out, ~2.25 GB of traffic). Eager/torch.compile do
// this as a gather into a fresh tensor; here it is a single pass where each
// output element is written exactly once and the two source streams are read
// independently so the memory system can overlap them.
//
// MetaX C500 notes (warp size 64, 104 SMs):
//  * float4 (16 B) vector loads/stores for coalesced wide transfers.
//  * Fixed grid of 1024 blocks with a grid-stride loop: a one-thread-per-element
//    grid measured only 338-642 GB/s on this device, while a fixed ~1024-block
//    grid-stride loop reaches 1227-1319 GB/s against a ~1350 GB/s ceiling.
//  * Consecutive threads touch consecutive addresses in both the read and the
//    write stream, so every transaction is coalesced.

#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void fused_stack_kernel_impl(
    float4* __restrict__ out,      // 2 * vn float4 slots: [x-block | y-block]
    const float4* __restrict__ x,  // vn float4 slots
    const float4* __restrict__ y,  // vn float4 slots
    long long vn)
{
    const long long tid = (long long)blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const long long stride = (long long)BLOCK_SIZE * gridDim.x;
    const float4* srcs[2] = {x, y};

    // Grid-stride loop: thread tid writes float4 lanes tid, tid+stride, ... in
    // each output half. Two independent load streams, one store stream.
    for (long long base = 0; base < vn; base += stride) {
        const long long i = base + tid;
        if (i < vn) {
            float4 a = x[i];
            float4 b = y[i];
            out[i] = a;
            out[vn + i] = b;
        }
    }
    (void)srcs;
}

// Scalar tail kernel, used only when n is not a multiple of 4.
__global__ void fused_stack_tail_impl(
    float* out, const float* x, const float* y, long long n)
{
    const long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    const long long stride = (long long)blockDim.x * gridDim.x;
    for (long long i = tid; i < n; i += stride) {
        float a = x[i];
        float b = y[i];
        out[i] = a;
        out[n + i] = b;
    }
}

// C-interface launcher (no PyTorch dependencies).
extern "C" void fused_stack_launcher(
    float* out,
    const float* x,
    const float* y,
    long long n,                 // float elements per source tensor
    cudaStream_t stream)
{
    const long long v = n / 4;   // float4 count per source tensor
    const long long tail = n - 4 * v;

    if (v > 0) {
        const int BLOCK_SIZE = 256;
        // Fixed grid saturates the 104 SMs without a per-element block explosion;
        // the grid-stride loop covers arbitrarily large tensors.
        long long blocks_needed = (v + BLOCK_SIZE - 1) / BLOCK_SIZE;
        int grid = (blocks_needed < 1024) ? (int)blocks_needed : 1024;
        if (grid < 1) grid = 1;

        fused_stack_kernel_impl<256><<<grid, BLOCK_SIZE, 0, stream>>>(
            (float4*)out, (const float4*)x, (const float4*)y, v);
    }

    if (tail > 0) {
        const int BLOCK_SIZE = 128;
        long long blocks_needed = (tail + BLOCK_SIZE - 1) / BLOCK_SIZE;
        int grid = (blocks_needed < 256) ? (int)blocks_needed : 256;
        if (grid < 1) grid = 1;
        fused_stack_tail_impl<<<grid, BLOCK_SIZE, 0, stream>>>(
            out + 4 * v, x + 4 * v, y + 4 * v, tail);
    }
}

