#include <cuda_runtime.h>

// Fused stack([x, y], dim=0) with interleaved write pattern.
// Each thread handles a (2 * VALUES_PER_THREAD)-element block:
//   even element slots <- x, odd element slots <- y.
// Convert to float2 vectorized loads/stores where possible.
template<int BLOCK_THREADS, int VPT>
__global__ void fused_stack_kernel(
    float* __restrict__ out,
    const float* __restrict__ x,
    const float* __restrict__ y,
    long long numel)
{
    long long tid = (long long)blockIdx.x * BLOCK_THREADS + threadIdx.x;
    long long stride = (long long)BLOCK_THREADS * gridDim.x;

    long long pos = tid * (2LL * VPT);
    long limit = (long)(numel);

    #pragma unroll
    for (int v = 0; v < VPT; ++v) {
        long long p = pos + (long long)v;
        if (p < limit) {
            long long oi = 2LL * p;
            out[oi] = x[p];
            out[oi + 1] = y[p];
        }
    }
    // grid-stride continuation
    for (long long base = pos + (long long)(2LL * VPT) * stride; base < limit;
         base += (long long)(2LL * VPT) * stride) {
        #pragma unroll
        for (int v = 0; v < VPT; ++v) {
            long long p = base + (long long)v;
            if (p < limit) {
                long long oi = 2LL * p;
                out[oi] = x[p];
                out[oi + 1] = y[p];
            }
        }
    }
}

extern "C" void fused_stack_launcher(
    float* output,
    const float* x,
    const float* y,
    long long numel,
    cudaStream_t stream)
{
    if (numel <= 0) return;

    const int BLOCK_THREADS = 256;
    const int VPT = 4;
    long long total_pairs = numel;
    long long pairs_per_block = (long long)BLOCK_THREADS * VPT;
    long long blocks = (total_pairs + pairs_per_block - 1) / pairs_per_block;
    if (blocks > 65536LL) blocks = 65536LL;

    fused_stack_kernel<BLOCK_THREADS, VPT><<< (unsigned int)blocks, BLOCK_THREADS, 0, stream >>>(
        output, x, y, (long long)numel);
}

