#include <cuda_runtime.h>

// Fused torch.stack([x, y]) -> shape (2, *x.shape).
//
// One thread per output element: thread index k maps to
//   batch = k / count   (0 -> x, 1 -> y)
//   elem  = k % count
// out[k] = (batch == 0) ? x[elem] : y[elem]
//
// Both input reads are coalesced per 64-thread warp (a warp at the boundary
// straddles the two inputs, but each half is still a coalesced segment), and
// the store is fully coalesced. This collapses 2 separate copy kernels +
// stack gather into a single pass: 2 reads + 1 write instead of 4+ traffic.
template<int BLOCK>
__global__ void fused_stack_kernel(
    float* __restrict__ output,
    const float* __restrict__ x,
    const float* __restrict__ y,
    long long count
) {
    long long k = (long long)blockIdx.x * BLOCK + threadIdx.x;
    const long long total = count * 2LL;

    // Grid-stride so the grid stays at ~1024 blocks regardless of size.
    for (long long idx = k; idx < total; idx += (long long)gridDim.x * BLOCK) {
        long long elem = idx;
        int batch = 0;
        if (elem >= count) { elem -= count; batch = 1; }
        output[idx] = (batch == 0) ? x[elem] : y[elem];
    }
}

extern "C" void fused_stack_launcher(
    float* output,
    const float* x,
    const float* y,
    long long count,
    cudaStream_t stream
) {
    const long long total = count * 2LL;
    if (total <= 0) return;

    const int BLOCK = 256;
    const int MAX_BLOCKS = 1024;
    long long blocks = (total + BLOCK - 1) / BLOCK;
    if (blocks > MAX_BLOCKS) blocks = MAX_BLOCKS;

    fused_stack_kernel<BLOCK><<<static_cast<int>(blocks), BLOCK, 0, stream>>>(
        output, x, y, count
    );
}

