#include <cuda_runtime.h>

// Fused ReLU + Identity: out = max(x, 0.0f).
// Memory-bound on C500: use float4 vectorized loads/stores with a fixed
// grid of 1024 blocks doing grid-stride loops (104 SMs, warp size 64).
// Previous scalar one-thread-per-element version reached only ~340-640 GB/s
// due to a far-too-fine grid; this layout targets ~1300 GB/s.

template<int BLOCK_SIZE, int VEC>
__global__ void fused_relu_identity_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    // Vectorized body: each thread handles VEC elements per iteration.
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    int aligned = size & (~(VEC - 1));  // largest multiple of VEC <= size

    // Vectorized pass (exact multiples of VEC)
    for (int i = tid * VEC; i < aligned; i += stride * VEC) {
        float4 in;
        in = *reinterpret_cast<const float4*>(input + i);
        float4 out;
        out.x = fmaxf(in.x, 0.0f);
        out.y = fmaxf(in.y, 0.0f);
        out.z = fmaxf(in.z, 0.0f);
        out.w = fmaxf(in.w, 0.0f);
        *reinterpret_cast<float4*>(output + i) = out;
    }

    // Scalar tail for remaining elements (size % VEC)
    int tail_base = aligned;
    for (int j = tid; j < (size - tail_base); j += stride) {
        int idx = tail_base + j;
        output[idx] = fmaxf(input[idx], 0.0f);
    }
}

extern "C" void fused_relu_identity_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    // Fixed grid of 1024 blocks regardless of size: keeps occupancy near
    // 1024*256/64 = 4096 warps across 104 SMs (~39 warps/SM) and uses a
    // grid-stride loop, avoiding the 768K-block granularity trap.
    const int BLOCK_SIZE = 256;
    const int GRID = 1024;

    int vec = 4;
    if (config == 1) vec = 2;   // float2 variant
    if (config == 2) vec = 1;   // scalar variant

    // Fall back to scalar if pointers aren't 4-byte aligned or size too small
    if (vec == 4) {
        if (((uintptr_t)input & 15) || ((uintptr_t)output & 15)) vec = 1;
    }

    if (vec == 4) {
        fused_relu_identity_kernel<BLOCK_SIZE, 4><<<GRID, BLOCK_SIZE, 0, stream>>>(
            output, input, size);
    } else if (vec == 2) {
        fused_relu_identity_kernel<BLOCK_SIZE, 2><<<GRID, BLOCK_SIZE, 0, stream>>>(
            output, input, size);
    } else {
        fused_relu_identity_kernel<BLOCK_SIZE, 1><<<GRID, BLOCK_SIZE, 0, stream>>>(
            output, input, size);
    }
}

