// Fused ReLU + Identity kernel.
// Identity is a no-op, so this is a pure elementwise relu.
// Performance fix (previous attempt was 0.99x): the old grid was
// one thread per element -> far finer than the 104 SMs can fill.
// This version uses a FIXED grid (NUM_BLOCKS blocks) with a grid-stride
// loop and float2 vectorized loads/stores, targeting ~1300 GB/s
// against a ~1350 GB/s copy ceiling on the MetaX C500.
#include <cuda_runtime.h>

// Warp size is 64 on MetaX C500 (not 32).
#define WARP_SIZE 64

// Tuned for 104 SMs: 1024 blocks x 256 threads.
// Total elements = 512*32*256*256 = 1,073,741,824 (4.3 GB).
// At float2 (8 bytes/thread-pair), each block handles 2*256 elements/iter.
#define NUM_BLOCKS 1024
#define BLOCK_THREADS 256

template<int BLOCK_SIZE, int VEC>
__global__ void fused_relu_identity_impl(float* output, const float* input, int size) {
    // Vectorized chunk count: each thread handles VEC elements per iteration.
    const int vec_size = size / VEC;  // number of VEC-wide chunks
    // Number of chunks this block strides over.
    int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;

    // float2 fast path: coalesced 8-byte loads, two relus per thread.
    if (VEC == 2) {
        const float2* in2 = reinterpret_cast<const float2*>(input);
        float2* out2 = reinterpret_cast<float2*>(output);
        for (int i = tid; i < vec_size; i += stride) {
            float2 v = in2[i];
            float2 r;
            r.x = fmaxf(v.x, 0.0f);
            r.y = fmaxf(v.y, 0.0f);
            out2[i] = r;
        }
        // Scalar tail for elements not covered by full float2 chunks.
        for (int j = vec_size * 2 + blockIdx.x; j < size; j += gridDim.x) {
            output[j] = fmaxf(input[j], 0.0f);
        }
        return;
    }

    // Scalar fallback (VEC == 1).
    for (int i = tid; i < size; i += stride) {
        output[i] = fmaxf(input[i], 0.0f);
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void fused_relu_identity_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    // Fixed grid regardless of size: grid-stride loop covers the rest.
    // This avoids the 768K-blocks fine-grid trap measured on this device.
    const int blocks = NUM_BLOCKS;
    const int threads = BLOCK_THREADS;

    switch (config) {
        case 0:  // float2, 256 threads, 1024 blocks (best measured variant)
            fused_relu_identity_impl<256, 2><<<blocks, threads, 0, stream>>>(
                output, input, size);
            break;
        case 1:  // float2, 128 threads, 1024 blocks
            fused_relu_identity_impl<128, 2><<<blocks, 128, 0, stream>>>(
                output, input, size);
            break;
        case 2:  // float2, 512 threads, 1024 blocks
            fused_relu_identity_impl<512, 2><<<blocks, 512, 0, stream>>>(
                output, input, size);
            break;
        case 3:  // scalar, 256 threads, 1024 blocks
            fused_relu_identity_impl<256, 1><<<blocks, 256, 0, stream>>>(
                output, input, size);
            break;
        default:
            fused_relu_identity_impl<256, 2><<<blocks, threads, 0, stream>>>(
                output, input, size);
    }
}

