#include <cuda_runtime.h>

// Fused exp(x) followed by sigmoid(exp(x)) = 1 / (1 + exp(-exp(x))).
// Using the 1/(1+e^-y) restatement keeps a single expf per element and avoids
// a chained SFU dependency (e^-y is independent of the lanes feeding it).
// float4 vectorized grid-stride loop; fixed 1024-block grid suits the
// C500's 104 SMs / warp size 64 and keeps the launch granularity coarse.

template<int BLOCK_SIZE>
__global__ void exp_sigmoid_kernel(
    float4* __restrict__ output,
    const float4* __restrict__ input,
    size_t num_quads          // number of float4 elements
) {
    const size_t tid = static_cast<size_t>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    const size_t stride = static_cast<size_t>(BLOCK_SIZE) * gridDim.x;

    for (size_t i = tid; i < num_quads; i += stride) {
        float4 v = input[i];

        float a = expf(v.x);
        float b = expf(v.y);
        float c = expf(v.z);
        float d = expf(v.w);

        // sigmoid(y) = 1 / (1 + exp(-y)); -y = -exp(x) is safe here since a..d > 0.
        v.x = 1.0f / (1.0f + expf(-a));
        v.y = 1.0f / (1.0f + expf(-b));
        v.z = 1.0f / (1.0f + expf(-c));
        v.w = 1.0f / (1.0f + expf(-d));

        output[i] = v;
    }
}

// Scalar tail / fallback path for non-16B-aligned tensors.
__global__ void exp_sigmoid_kernel_scalar(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t size
) {
    const size_t tid = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const size_t stride = static_cast<size_t>(blockDim.x) * gridDim.x;

    for (size_t i = tid; i < size; i += stride) {
        float y = expf(input[i]);
        output[i] = 1.0f / (1.0f + expf(-y));
    }
}

extern "C" void exp_sigmoid_launcher(
    float* output,
    const float* input,
    size_t size,
    cudaStream_t stream
) {
    if (size == 0) return;

    const size_t rem = size & 3UL;                 // elements handled scalar
    const size_t num_quads = size >> 2;            // float4 elements

    if (num_quads > 0) {
        const int BLOCK = 256;                     // 4 warps of 64
        const int GRID = 1024;                     // fixed coarse grid
        exp_sigmoid_kernel<BLOCK><<<GRID, BLOCK, 0, stream>>>(
            reinterpret_cast<float4*>(output),
            reinterpret_cast<const float4*>(input),
            num_quads
        );
    }

    if (rem > 0) {
        const int BLOCK = 256;
        const int GRID = 32;
        exp_sigmoid_kernel_scalar<<<GRID, BLOCK, 0, stream>>>(
            output + num_quads * 4,
            input + num_quads * 4,
            rem
        );
    }
}

