// Fused exp(x) -> sigmoid(exp(x)) for MetaX C500.
// Memory-bound elementwise: single pass reads x once, writes y once.
// exp(x) is held in a register, so the second op costs no extra traffic.
// Vectorized float2 loads + fixed 1024-block grid-stride loop (per MACA
// guidance: fine grids are a trap on this device; warp size is 64).
#include <cuda_runtime.h>

#ifdef __CUDACC__
#define HD __host__ __device__
#else
#define HD
#endif

// tanh-based rational approximation of sigmoid: 0.5 + 0.5*tanh(0.5*z).
// sigmoid(1.0) == 1/(1+e^-1); tanh form avoids the reciprocal chain
// (rcp(expf) would serialize two SFU-dependent ops).
HD static inline float sig_from_exp(float e) {
    // e = exp(x), e >= 0 for all real x.
    // sigmoid(x) = e / (1 + e) = 1 / (1 + 1/e).
    // Restate with tanh of half-log to keep it branch-free and SFU-light:
    //   sigmoid(x) = 0.5 + 0.5 * tanh(x/2)
    // but we only have e = exp(x); x/2 = 0.5*log(e) costs a log SFU.
    // Instead use the direct stable form: e/(1+e) computed via rcp(1+1/e).
    float ei = 1.0f / e;          // e > 0 always; e may overflow to +inf -> ei = 0
    float denom = 1.0f + ei;      // >= 1, no overflow
    return 1.0f / denom;          // in (0,1], matches sigmoid exactly
}

__global__ void exp_sigmoid_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t size)
{
    // Base pointer arithmetic uses size_t to avoid int overflow at 537M elems.
    const size_t tid = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
    const size_t stride = (size_t)blockDim.x * gridDim.x;

    // Vectorized body: 2 floats per thread iteration.
    const size_t v_size = size >> 1;
    const float2* in2 = (const float2*)input;
    float2* out2 = (float2*)output;

    for (size_t i = tid; i < v_size; i += stride) {
        float2 v = in2[i];
        float2 r;
        r.x = sig_from_exp(expf(v.x));
        r.y = sig_from_exp(expf(v.y));
        out2[i] = r;
    }

    // Tail: odd element.
    if ((size & 1ULL) != 0ULL) {
        size_t last = size - 1ULL;
        if (tid == 0ULL) {
            output[last] = sig_from_exp(expf(input[last]));
        }
    }
}

extern "C" void exp_sigmoid_launcher(
    float* output,
    const float* input,
    size_t size,
    unsigned long long stream)
{
    // 256 threads/block * 1024 blocks = 262144 threads, each handling 2
    // elements per stride step -> covers 524288 elems/stride. Grid-stride
    // loop handles the rest. 256 threads = 4 warps of 64 lanes on C500.
    const int threads = 256;
    const int blocks = 1024;
    exp_sigmoid_kernel<<<blocks, threads, 0, (cudaStream_t)stream>>>(
        output, input, size);
}

