#include <cuda_runtime.h>

// Fused ReLU + ReLU6: y = relu6(relu(x)) = min(max(x, 0), 6).
// Pure memory-bound elementwise op, so the goal is one pass over memory:
//   unfused: read x, write t, read t, write y  (3 full tensors of traffic)
//   fused:   read x, write y                   (2 tensors)
// Vectorized float2 loads + a fixed coarse grid-stride loop: on the C500
// (warp 64, 104 SMs) a fine one-thread-per-element grid stalls at ~600 GB/s
// while a 1024-block grid-stride loop with float2 reaches ~1300 GB/s.

template<int BLOCK_SIZE>
__global__ void fused_relu_relu6_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    long long size
) {
    // Half the threads work in float2 pairs; a total of BLOCK_SIZE float
    // elements are produced per iteration of the block.
    const int lane = threadIdx.x;
    const long long base = (long long)blockIdx.x * (long long)BLOCK_SIZE + (long long)lane;
    const long long stride = (long long)BLOCK_SIZE * (long long)gridDim.x;

    // Aligned float2 body: process pairs while a whole pair fits.
    long long n2 = (size >> 1);
    long long i2 = base >> 1;  // this thread's initial pair index

    if ((lane & 1) == 0) {
        // Even lanes own the float2 loads (2 elements each).
        float2* out2 = reinterpret_cast<float2*>(output);
        const float2* in2 = reinterpret_cast<const float2*>(input);
        for (long long i = i2; i < n2; i += (long long)(BLOCK_SIZE >> 1)) {
            float2 v = in2[i];
            v.x = fminf(fmaxf(v.x, 0.0f), 6.0f);
            v.y = fminf(fmaxf(v.y, 0.0f), 6.0f);
            out2[i] = v;
        }
    } else {
        // Odd lanes handle the tail (odd element count) scalar-wise.
        for (long long i = base; i < size; i += stride) {
            float v = input[i];
            output[i] = fminf(fmaxf(v, 0.0f), 6.0f);
        }
    }
}

extern "C" void fused_relu_relu6_launcher(
    float* output,
    const float* input,
    long long size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;          // 4 warps of 64
    // Coarse, fixed grid: ~2 waves on 104 SMs. Grid-stride handles the tail.
    const int GRID = 1024;

    fused_relu_relu6_kernel<BLOCK_SIZE><<<GRID, BLOCK_SIZE, 0, stream>>>(
        output, input, size
    );
}

