#include <cuda_runtime.h>

// Fused ReLU + ReLU6:  y = min(max(x, 0), 6)
// Memory-bound elementwise op: single pass over x, so traffic = read x + write y
// (vs. 4 passes for the two unfused ops). Vectorized float2 loads with a fixed
// 1024-block grid-stride loop to keep the 104 SMs fed without an over-fine grid.
template<int BLOCK_SIZE>
__global__ void fused_relu_relu6_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    // float2 processing: each thread handles 2 elements
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    int n2 = size >> 1;
    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

    #pragma unroll 1
    for (int i = tid; i < n2; i += stride) {
        float2 v = in2[i];
        float2 r;
        r.x = fminf(fmaxf(v.x, 0.0f), 6.0f);
        r.y = fminf(fmaxf(v.y, 0.0f), 6.0f);
        out2[i] = r;
    }

    // Handle the odd tail element, if any
    if ((size & 1) != 0) {
        int last = size - 1;
        for (int i = tid; i <= last; i += stride) {
            float v = input[i];
            output[i] = fminf(fmaxf(v, 0.0f), 6.0f);
        }
    }
}

extern "C" void fused_relu_relu6_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;       // 4 warps of 64 threads each
    // Fixed grid: enough blocks to fill all 104 SMs several times over,
    // but far coarser than one block per element pair.
    const int GRID = 1024;

    fused_relu_relu6_kernel<BLOCK_SIZE><<<GRID, BLOCK_SIZE, 0, stream>>>(
        output, input, size
    );
}

