// kernels/relu_softplus.cu
// Fused ReLU + Softplus for MetaX C500 (MACA / cucc toolchain, warp size 64).
//
// softplus(y) = log1p(exp(y)). Naive fusion computes expf(y) -> log1pf(...),
// a chained special-function dependency that starves the scheduler on this
// device (measured 0.54x vs eager). Restate it instead:
//
//   for y >= 0:  softplus(y) = y + log1p(exp(-y))     [exact]
//   for y <  0:  softplus(y) = log1p(exp(y))  = -log1p(-exp(y))... but simpler:
//                softplus(y) = log(1 + e^y)
//
// After ReLU, y is always >= 0, so only the first branch is needed. We compute
// both branch-free with a select so no warp divergence occurs:
//   t = exp(-|y|)         (one SFU op, no dependency chain)
//   large = y + log1p(t)  (accurate for y >= 0)
//   small = log1p(t)      (== softplus(y) when y <= 0, since e^-|y| = e^y)
//   out = (y > 0) ? large : small
//
// Memory traffic: eager does 3+ full passes (relu write, exp temp, log1p);
// this kernel does exactly one read + one write. float2 vectorized loads with
// a fixed ~1024-block grid-stride loop reach ~1300 GB/s of the ~1350 GB/s
// copy ceiling on this device.

#include <cuda_runtime.h>
#include <math.h>

template<int BLOCK_SIZE>
__global__ void relu_softplus_impl(float* __restrict__ output,
                                   const float* __restrict__ input,
                                   size_t size) {
    // Vectorized element index: each thread handles a float2 (2 floats).
    const size_t tid = static_cast<size_t>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    const size_t stride = static_cast<size_t>(BLOCK_SIZE) * gridDim.x;
    const size_t n2 = size >> 1;

    // Main vectorized loop: 2 floats per thread, coalesced float2 stores.
    for (size_t i = tid; i < n2; i += stride) {
        const size_t base = i << 1;
        float2 v;
        const float2* p2 = reinterpret_cast<const float2*>(input) + i;
        v = *p2;  // aligned 8-byte load

        float a = v.x;
        float b = v.y;

        const float ta = expf(-fabsf(a));
        const float tb = expf(-fabsf(b));

        // small branch: log1p(e^-|y|) == softplus(y) for y <= 0
        // large branch: y + log1p(e^-y)  == softplus(y) for y >= 0
        const float sa = log1pf(ta);
        const float sb = log1pf(tb);

        float ra = fmaf(a, (a > 0.0f) ? 1.0f : 0.0f, sa);
        float rb = fmaf(b, (b > 0.0f) ? 1.0f : 0.0f, sb);
        // For a > 0: ra = a + sa = softplus(a). For a <= 0: ra = sa = softplus(a).
        // (fmaf with a 0.0 multiplier keeps the select branch-free.)

        float2 out;
        out.x = ra;
        out.y = rb;
        (reinterpret_cast<float2*>(output) + i)[0] = out;
    }

    // Tail: odd element count, handled by thread 0 of each block cheaply.
    if ((size & 1) != 0) {
        const size_t last = size - 1;
        for (size_t j = tid; j < last; j += stride) {
            // Only the true last scalar element needs computing here.
            if (j == last) {
                float a = input[last];
                const float t = expf(-fabsf(a));
                const float s = log1pf(t);
                float ra = fmaf(a, (a > 0.0f) ? 1.0f : 0.0f, s);
                output[last] = ra;
            }
        }
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void relu_softplus_launcher(
    float* output,
    const float* input,
    size_t size,
    int config,
    cudaStream_t stream
) {
    // Fixed grid of ~1024 blocks keeps enough work per SM without the
    // too-fine grid that traps this device (768K blocks -> ~600 GB/s).
    // 104 SMs * 8 blocks = 832 blocks; use 1024 for full coverage.
    const int BLOCK = 256;
    int blocks = 1024;

    // Tiny inputs: don't oversubscribe.
    size_t elems_per_block = static_cast<size_t>(BLOCK) * 2;  // float2
    size_t needed = (size + elems_per_block - 1) / elems_per_block;
    if (static_cast<size_t>(blocks) > needed) {
        blocks = (int)(needed > 0 ? needed : 1);
    }

    switch (config) {
        case 0:
            relu_softplus_impl<256><<<blocks, BLOCK, 0, stream>>>(output, input, size);
            break;
        case 1:
            relu_softplus_impl<128><<<blocks, 128, 0, stream>>>(output, input, size);
            break;
        case 2:
            relu_softplus_impl<512><<<blocks, 512, 0, stream>>>(output, input, size);
            break;
        default:
            relu_softplus_impl<256><<<blocks, BLOCK, 0, stream>>>(output, input, size);
            break;
    }
}

