#include <cuda_runtime.h>

// Fused ReLU + Softplus:  y = relu(x);  out = softplus(y) = log(1 + exp(y))
// For z >= 0 use log1p(exp(z)); for z < 0 use log1p(exp(z)) computed as
// log(1+e^z). Since ReLU clamps negatives to 0, the softplus input is z >= 0,
// and log1p(exp(z)) is numerically stable for z >= 0 up to large z.
// To avoid the expf->log1pf chained-SFU dependency we use the algebraic
// restatement: log1p(e^z) = z + log1p(e^-z), valid for all z and requiring
// only one expf on -z whose result feeds a cheap add.
//
// Total elements here (2048*1024*1024) exceed int32 range, so all indexing
// uses 64-bit quantities.

template<int BLOCK_SIZE>
__global__ void relu_softplus_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    long long size
) {
    const long long base = (long long)blockIdx.x * (long long)BLOCK_SIZE;
    const int tid = threadIdx.x;
    const long long step = (long long)BLOCK_SIZE;

    // Vectorized float2 grid-stride loop with fixed 1024-block grid.
    for (long long pos = base; pos < size; pos += 1024LL * step) {
        long long i0 = pos + (tid >> 1) * 2;
        if (i0 < size) {
            float2 in;
            if ((i0 & 1) == 0 && i0 + 1 < size) {
                in = *reinterpret_cast<const float2*>(input + i0);
            } else {
                in.x = input[i0];
                in.y = (i0 + 1 < size) ? input[i0 + 1] : 0.0f;
            }

            float a = fmaxf(in.x, 0.0f);
            float b = fmaxf(in.y, 0.0f);

            // stable: softplus(u) = u + log1p(exp(-u)) for u >= 0
            float oa = a + log1pf(expf(-a));
            float ob = b + log1pf(expf(-b));

            if ((i0 & 1) == 0 && i0 + 1 < size) {
                *reinterpret_cast<float2*>(output + i0) = make_float2(oa, ob);
            } else {
                output[i0] = oa;
                if (i0 + 1 < size) output[i0 + 1] = ob;
            }
        }
    }
}

extern "C" void relu_softplus_launcher(
    float* output,
    const float* input,
    long long size,
    cudaStream_t stream
) {
    const int BLOCK = 256;
    int blocks = 1024;
    if (size <= (long long)BLOCK) {
        blocks = (int)((size + BLOCK - 1) / BLOCK);
        if (blocks < 1) blocks = 1;
    }
    relu_softplus_kernel<BLOCK><<<blocks, BLOCK, 0, stream>>>(output, input, size);
}

