// kernels/relu_softplus.cu
// Fused relu + softplus for MetaX C500 (warp size 64, 104 SMs).
//
// relu(x) = max(x, 0); softplus(y) = log(1 + e^y).
// After relu, y >= 0. For y >= 0 use the numerically stable form
//   softplus(y) = y + log1p(exp(-y))
// which avoids computing exp(large) and breaks the expf->log1pf dependency
// chain that starves the SFU scheduler on this device.
//
// Memory pattern: float2 vector loads/stores with a fixed 1024-block
// grid-stride loop (measured ~1300 GB/s vs ~600 GB/s for a scalar
// one-thread-per-element kernel). Tail elements are handled by a scalar
// cleanup loop so no out-of-bounds accesses occur.

#include <cuda_runtime.h>
#include <math.h>

#ifndef C500_BLOCK_SIZE
#define C500_BLOCK_SIZE 256
#endif

__device__ __forceinline__ float softplus_nonneg(float y) {
    // y >= 0 here (post-ReLU). y + log1p(exp(-y)) is exact for all y >= 0:
    //   y == 0 -> 0 + log1p(1) = log(2)
    //   y large -> exp(-y) ~ 0, result ~ y
    float z = expf(-y);
    return y + log1pf(z);
}

__global__ void relu_softplus_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size)
{
    const int64_t tid = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    const int64_t total = (int64_t)blockDim.x * gridDim.x;

    // Vectorized body: each thread handles float2 pairs, striding by grid.
    const int64_t vtid = tid;
    const int64_t vtotal = total;
    int64_t i = vtid * 2;
    const int64_t aligned_end = size & ~1LL;

    const float2* in2 = reinterpret_cast<const float2*>(input);
    float2* out2 = reinterpret_cast<float2*>(output);

    while (i < aligned_end) {
        float2 v = in2[i >> 1];
        float a = fmaxf(v.x, 0.0f);
        float b = fmaxf(v.y, 0.0f);
        float2 r;
        r.x = softplus_nonneg(a);
        r.y = softplus_nonneg(b);
        out2[i >> 1] = r;
        i += vtotal * 2;
    }

    // Scalar tail for odd-sized inputs (and any straggler element).
    // Guarded strictly by size so no OOB reads/writes happen.
    int64_t j = tid;
    while (j < size) {
        float v = input[j];
        float a = fmaxf(v, 0.0f);
        output[j] = softplus_nonneg(a);
        j += total;
    }
}

extern "C" void relu_softplus_launcher(
    float* output,
    const float* input,
    int64_t size,
    cudaStream_t stream)
{
    // Fixed, modest grid: 1024 blocks of 256 threads = 262144 lanes.
    // Grid-stride loops cover any size; a huge per-element grid is a
    // documented performance trap on C500 and can exceed launch limits.
    const int threads = C500_BLOCK_SIZE;
    int blocks = 1024;

    // For tiny inputs, don't oversubscribe: one element per lane is enough.
    // blocks*threads must be >= 1; keep blocks small so the tail loop is a
    // no-op for most sizes and never out of bounds.
    if (size < (int64_t)blocks * threads) {
        // ceil(size / threads) but at least 1
        int64_t b = (size + threads - 1) / threads;
        if (b < (int64_t)blocks) blocks = (int)b;
        if (blocks < 1) blocks = 1;
    }

    relu_softplus_kernel<<<blocks, threads, 0, stream>>>(output, input, size);
}

