#include <cuda_runtime.h>

// Fused relu(x) -> relu(x) : identical to a single relu, but the two-op
// chain is fused into one memory pass. Memory-bound on MetaX C500, so we
// use float4 vector loads/stores with a fixed ~1024-block grid-stride loop
// (fine-grained one-thread-per-element grids only reach ~600 GB/s here,
// vectorized fixed-grid reaches ~1300 GB/s against a ~1350 GB/s ceiling).

template<int BLOCK_SIZE>
__global__ void fused_relu_relu_kernel(
    float4* __restrict__ output,
    const float4* __restrict__ input,
    size_t num_quads   // number of float4 elements
) {
    size_t tid = static_cast<size_t>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    size_t stride = static_cast<size_t>(BLOCK_SIZE) * gridDim.x;

    #pragma unroll 1
    for (size_t i = tid; i < num_quads; i += stride) {
        float4 v = input[i];
        v.x = fmaxf(v.x, 0.0f);
        v.y = fmaxf(v.y, 0.0f);
        v.z = fmaxf(v.z, 0.0f);
        v.w = fmaxf(v.w, 0.0f);
        output[i] = v;
    }
}

extern "C" void fused_relu_relu_launcher(
    float* output,
    const float* input,
    size_t size,
    cudaStream_t stream
) {
    // Whole tensor size is a multiple of 4 in practice; handle remainder safely.
    size_t num_quads = size / 4;
    size_t rem = size - num_quads * 4;

    if (num_quads > 0) {
        const int BLOCK_SIZE = 256;
        // Fixed grid of 1024 blocks: 262144 threads covers the whole tensor
        // up to 1M elements in one pass; grid-stride beyond that.
        int grid = (int)((num_quads + BLOCK_SIZE - 1) / BLOCK_SIZE);
        const int MAX_GRID = 1024;
        if (grid > MAX_GRID) grid = MAX_GRID;
        if (grid < 1) grid = 1;

        fused_relu_relu_kernel<256><<<grid, BLOCK_SIZE, 0, stream>>>(
            reinterpret_cast<float4*>(output),
            reinterpret_cast<const float4*>(input),
            num_quads
        );
    }

    // Scalar tail for non-multiple-of-4 sizes (normally zero elements).
    if (rem > 0) {
        size_t base = num_quads * 4;
        const int BLOCK_SIZE = 256;
        int grid = (int)((rem + BLOCK_SIZE - 1) / BLOCK_SIZE);
        if (grid < 1) grid = 1;
        fused_relu_relu_kernel<256><<<grid, BLOCK_SIZE, 0, stream>>>(
            reinterpret_cast<float4*>(output + base),
            reinterpret_cast<const float4*>(input + base),
            (rem + 3) / 4
        );
    }
}

