#include <cuda_runtime.h>

// Fused relu(x) followed by relu(x): mathematically relu(relu(x)) == relu(x).
// Implemented as a single pass with float2 vectorized loads and a fixed
// 1024-block grid-stride loop, sized for the MetaX C500 (104 SMs, warp 64).
// A warp of 64 threads processes 128 floats per iteration.

template<int BLOCK_SIZE>
__global__ void fused_relu_relu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    // Vectorized base pointer; size is a multiple of 2 for this task.
    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);
    const int n2 = size >> 1;

    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    #pragma unroll 1
    for (int i = tid; i < n2; i += stride) {
        float2 v = __ldg(&in2[i]);
        float a = v.x > 0.0f ? v.x : 0.0f;
        float b = v.y > 0.0f ? v.y : 0.0f;
        float2 r;
        r.x = a > 0.0f ? a : 0.0f;   // second relu
        r.y = b > 0.0f ? b : 0.0f;
        out2[i] = r;
    }

    // Handle a possible odd tail element.
    if ((size & 1) != 0 && tid == 0) {
        float v = __ldg(&input[size - 1]);
        output[size - 1] = v > 0.0f ? v : 0.0f;
    }
}

// Roughly 4 waves of 64-thread warps across 104 SMs: 8 blocks/SM * 104 = 832,
// rounded up to 1024 for a fixed grid that keeps the SMs filled.
static const int FIXED_BLOCKS = 1024;

extern "C" void fused_relu_relu_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    const int block_size = 256;  // 4 warps of 64 -> 256 threads per block
    fused_relu_relu_kernel<256><<<FIXED_BLOCKS, block_size, 0, stream>>>(
        output, input, size);
}

