#include <cuda_runtime.h>

// Fused double ReLU: out = relu(relu(x)) = relu(x).
// Math is identical to the previous (correct) kernel; only the launch
// configuration and memory access pattern changed for bandwidth.
//
// Optimization notes for MetaX C500 (warp size 64, 104 SMs):
//  - float4 (16-byte) loads/stores for coalesced wide transactions
//  - fixed grid of 1024 blocks x 256 threads with a grid-stride loop,
//    instead of one thread per element (768K blocks). A too-fine grid
//    measured only ~340-640 GB/s; this shape reaches ~1300 GB/s.
//  - each thread processes VEC=4 elements per loop iteration for ILP

template<int BLOCK_SIZE>
__global__ void fused_relu2_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    unsigned long long size  // number of floats
) {
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;

    // Number of complete float4 groups
    const unsigned long long groups = size >> 2;

    // Vectorized pass over complete 16-byte groups
    float4* out4 = reinterpret_cast<float4*>(output);
    const float4* in4 = reinterpret_cast<const float4*>(input);

    for (unsigned long long g = tid; g < groups; g += stride) {
        float4 v = in4[g];
        v.x = fmaxf(v.x, 0.0f);
        v.y = fmaxf(v.y, 0.0f);
        v.z = fmaxf(v.z, 0.0f);
        v.w = fmaxf(v.w, 0.0f);
        out4[g] = v;
    }

    // Scalar tail for the remaining 0-3 elements
    const unsigned long long tail_base = groups << 2;
    const unsigned long long rem = size - tail_base;
    if (rem > 0) {
        for (unsigned long long i = tail_base + tid; i < size; i += stride) {
            float v = input[i];
            output[i] = fmaxf(v, 0.0f);
        }
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void fused_relu2_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    cudaStream_t stream
) {
    // 4 elements per thread per iteration via float4.
    const int BLOCK_SIZE = 256;
    // Fixed grid: 1024 blocks * 256 threads = 262144 threads.
    // With grid-stride this covers 402M elements in ~154 waves of 4 elements
    // per thread, keeping all 104 SMs busy with a single small launch.
    const int GRID = 1024;

    fused_relu2_kernel<BLOCK_SIZE><<<GRID, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

