// kernels/expm1_kernel.cu
// Fused single-pass expm1: out = exp(x) - 1
//
// Target: MetaX C500 (MACA), warp 64, 104 SMs, ~64 KB smem/block.
// Memory-bound elementwise op with a single SFU op per element.
// Strategy: float4 vectorized loads/stores + fixed 1024-block grid-stride
// loop so each thread does 4-wide coalesced access and 4 independent
// expf() issues give the scheduler ILP to hide SFU latency.

#include <cuda_runtime.h>

template<int BLOCK_SIZE, int VEC>
__global__ void expm1_kernel_impl(float* __restrict__ output,
                                  const float* __restrict__ input,
                                  size_t size) {
    // Scalar tail handling: we treat size as float count; vec loop covers
    // floor(size/VEC)*VEC elements, remainder handled by a scalar cleanup.
    size_t tid = (size_t)blockIdx.x * (size_t)BLOCK_SIZE + (size_t)threadIdx.x;
    const size_t total_threads = (size_t)gridDim.x * (size_t)BLOCK_SIZE;

    const size_t vec_count = size / (size_t)VEC;

    // Vectorized grid-stride loop: 4 elements per thread per iteration.
    for (size_t v = tid; v < vec_count; v += total_threads) {
        size_t base = v * (size_t)VEC;

        float4 in;
        const float4* src4 = reinterpret_cast<const float4*>(input + base);
        in = *src4;  // single 16-byte coalesced load

        float4 out;
        out.x = expf(in.x) - 1.0f;
        out.y = expf(in.y) - 1.0f;
        out.z = expf(in.z) - 1.0f;
        out.w = expf(in.w) - 1.0f;

        *reinterpret_cast<float4*>(output + base) = out;
    }

    // Scalar cleanup for the tail (size % VEC) elements.
    for (size_t i = vec_count * (size_t)VEC + tid;
         i < size;
         i += total_threads) {
        output[i] = expf(input[i]) - 1.0f;
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void expm1_kernel_launcher(
    float* output,
    const float* input,
    size_t size,
    int config,
    cudaStream_t stream
) {
    const size_t n = size;

    if (n == 0) return;

    // Fixed coarse grid: ~1024 blocks keeps enough waves over 104 SMs
    // without the too-fine-grid trap (768K blocks measured 338-642 GB/s).
    // Each thread handles VEC=4 elements per stride iteration.
    switch (config) {
        case 0: { // default: 256 threads * 1024 blocks, float4
            const int BLOCK = 256;
            int blocks = 1024;
            const size_t vec_elems = (n / 4) * 4;
            // Only shrink grid if the work is genuinely tiny.
            size_t needed = (vec_elems + (size_t)BLOCK * 4 - 1) /
                            ((size_t)BLOCK * 4);
            if ((size_t)blocks > needed && needed > 0) blocks = (int)needed;
            expm1_kernel_impl<256, 4><<<blocks, BLOCK, 0, stream>>>(
                output, input, n);
            break;
        }
        case 1: { // 128 threads, more blocks
            const int BLOCK = 128;
            int blocks = 2048;
            size_t needed = ((n / 4) * 4 + (size_t)BLOCK * 4 - 1) /
                            ((size_t)BLOCK * 4);
            if ((size_t)blocks > needed && needed > 0) blocks = (int)needed;
            expm1_kernel_impl<128, 4><<<blocks, BLOCK, 0, stream>>>(
                output, input, n);
            break;
        }
        case 2: { // 512 threads
            const int BLOCK = 512;
            int blocks = 512;
            size_t needed = ((n / 4) * 4 + (size_t)BLOCK * 4 - 1) /
                            ((size_t)BLOCK * 4);
            if ((size_t)blocks > needed && needed > 0) blocks = (int)needed;
            expm1_kernel_impl<512, 4><<<blocks, BLOCK, 0, stream>>>(
                output, input, n);
            break;
        }
        default: {
            const int BLOCK = 256;
            expm1_kernel_impl<256, 4><<<1024, BLOCK, 0, stream>>>(
                output, input, n);
            break;
        }
    }
}

