#include <cuda_runtime.h>
#include <cmath>

// Memory-bound expm1 kernel optimized for MetaX C500 (warp 64, 104 SMs).
// Strategy: float2 vectorized loads/stores + fixed grid (1024 blocks) with a
// grid-stride loop. 1024 blocks * 256 threads = 262144 threads, ~128 KB of
// vector elements in flight per wave, keeping all 104 SMs fed without the
// oversubscription penalty seen with one-block-per-element grids.

template<int BLOCK_SIZE>
__global__ void expm1_kernel_v2(float* __restrict__ output,
                                const float* __restrict__ input,
                                size_t size) {
    // Vectorized view: treat the flat array as float2 pairs.
    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

    size_t tid = (size_t)blockIdx.x * (size_t)BLOCK_SIZE + (size_t)threadIdx.x;
    size_t stride = (size_t)BLOCK_SIZE * (size_t)gridDim.x;

    size_t n2 = size >> 1;

    // Grid-stride loop over aligned float2 pairs.
    for (size_t i = tid; i < n2; i += stride) {
        float2 v = in2[i];
        float2 r;
        r.x = __expf(v.x) - 1.0f;
        r.y = __expf(v.y) - 1.0f;
        out2[i] = r;
    }

    // Tail: odd element count, handled by the first N/2 threads only.
    if ((size & 1ULL) != 0ULL && tid == 0) {
        float v = input[size - 1];
        output[size - 1] = __expf(v) - 1.0f;
    }
}

extern "C" void expm1_kernel_launcher(
    float* output,
    const float* input,
    size_t size,
    cudaStream_t stream
) {
    const int BLOCK_SIZE = 256;
    const int GRID = 1024;

    // Vectors per grid-stride iteration: 1024 * 256 = 262144 float2 = 512K floats.
    expm1_kernel_v2<BLOCK_SIZE><<<GRID, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

