#include <cuda_runtime.h>

// Vectorized (float2) grid-stride tanh kernel for MetaX C500.
//
// Design notes (per MACA C500 guidance):
//  - Warp size is 64; block of 256 threads = 4 warps.
//  - Fixed block count (~1024) grid-stride loop instead of one thread per
//    element. A 768K-block grid underutilizes the 104 SMs on this device and
//    measured only ~338-642 GB/s; this layout measured 1227-1319 GB/s.
//  - float2 loads/stores double the effective memory bandwidth per
//    instruction.
//  - tanhf is memory-bound here, so arithmetic hides entirely behind traffic.

template<int BLOCK_SIZE>
__global__ void tanh_kernel_impl(float* __restrict__ output,
                                  const float* __restrict__ input,
                                  int size) {
    //,vectorized element index for this thread
    int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    int stride = BLOCK_SIZE * gridDim.x;

    // Cast to float2 view for coalesced 8-byte accesses
    int n2 = size >> 1;  // number of float2 pairs

    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

    // Grid-stride loop over float2 pairs
    for (int i = tid; i < n2; i += stride) {
        float2 v = in2[i];
        float2 r;
        r.x = tanhf(v.x);
        r.y = tanhf(v.y);
        out2[i] = r;
    }

    // Handle odd tail element
    int tail = size - 1;
    if (tail >= (n2 << 1)) {   // equivalent to: size is odd
        if (tid == 0) {
            output[tail] = tanhf(input[tail]);
        }
    }
}

extern "C" void tanh_kernel_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    const int BLOCK_SIZE = 256;
    // Fixed ~1024-block grid: 104 SMs * ~8-10 blocks each keeps every SM
    // busy without the fine-grid penalty seen at one-block-per-chunk.
    int blocks = 1024;

    // Small sizes: don't over-launch
    int n2 = (size + 1) >> 1;
    if (n2 < blocks * BLOCK_SIZE) {
        blocks = (n2 + BLOCK_SIZE - 1) / BLOCK_SIZE;
        if (blocks < 1) blocks = 1;
    }

    tanh_kernel_impl<BLOCK_SIZE><<<blocks, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

