#include <cuda_runtime.h>
#include <cmath>

// Fused elementwise tanh, memory-traffic bound.
// Strategy for MetaX C500 (warp size 64, 104 SMs):
//   - fixed block count (1024 blocks) grid-stride loop: avoids the
//     one-thread-per-element grid that undersubscribes the SMs
//   - float4 vectorized loads/stores: coalesced 16-byte transactions
//   - 512 threads/block = 8 warps, good occupancy for a register-light kernel
// Each thread processes 4 floats per iteration -> effective block width 2048.
template<int BLOCK_SIZE>
__global__ void tanh_fwd_impl(float* __restrict__ output,
                              const float* __restrict__ input,
                              size_t n4) {
    const size_t stride = (size_t)BLOCK_SIZE * gridDim.x * 4;
    size_t idx = ((size_t)blockIdx.x * BLOCK_SIZE + threadIdx.x) * 4;

    for (size_t i = idx; i < n4; i += stride) {
        float4 v;
        v.x = tanhf(__ldg(input + i + 0));
        v.y = tanhf(__ldg(input + i + 1));
        v.z = tanhf(__ldg(input + i + 2));
        v.w = tanhf(__ldg(input + i + 3));
        *reinterpret_cast<float4*>(output + i) = v;
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void tanh_fwd_launcher(
    float* output,
    const float* input,
    size_t size,
    cudaStream_t stream
) {
    const int BLOCK_SIZE = 512;
    const int GRID = 1024;  // fixed grid: ~10 blocks/SM across 104 SMs
    size_t n4 = size;       // size is pre-rounded down to a multiple of 4

    tanh_fwd_impl<BLOCK_SIZE><<<GRID, BLOCK_SIZE, 0, stream>>>(output, input, n4);
}

