// kernels/leaky_relu.cu
// Fused leaky_relu(x, 0.01) = x > 0 ? x : 0.01 * x
//
// Single elementwise op on a contiguous float32 tensor: memory-bound, trivial
// arithmetic. The whole game on the MetaX C500 is memory throughput:
//   - scalar (1 thread / element) grids stall at ~600 GB/s
//   - float4 loads + fixed ~1024-block grid-stride loop reach ~1300 GB/s
// So we vectorize with float4 and cap the grid at 1024 blocks of 256 threads
// (104 SMs -> ~10 blocks/SM), grid-striding over the input.
//
// Traffic: read 2*N bytes + write 2*N bytes (N = numel). For the reference
// shape (16384 x 32768 = 512M floats = 2 GB) that is 4 GB -> ~3 ms at the
// device ceiling. Warp size on this device is 64.

#include <cuda_runtime.h>

__device__ __forceinline__ float4 leaky_relu4(float4 v) {
    const float slope = 0.01f;
    float4 out;
    out.x = v.x > 0.0f ? v.x : slope * v.x;
    out.y = v.y > 0.0f ? v.y : slope * v.y;
    out.z = v.z > 0.0f ? v.z : slope * v.z;
    out.w = v.w > 0.0f ? v.w : slope * v.w;
    return out;
}

// Vectorized grid-stride kernel. Each thread handles VEC floats per iteration.
template<int BLOCK_SIZE>
__global__ void leaky_relu_vec4_impl(float* __restrict__ output,
                                     const float* __restrict__ input,
                                     int n_vec) {
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;

    // Fast path: fully aligned 16-byte body.
    float4* out4 = reinterpret_cast<float4*>(output);
    const float4* in4 = reinterpret_cast<const float4*>(input);

    for (int i = tid; i < n_vec; i += stride) {
        out4[i] = leaky_relu4(in4[i]);
    }
}

// Scalar tail / fallback: handles any alignment and any remainder.
__global__ void leaky_relu_scalar_impl(float* __restrict__ output,
                                       const float* __restrict__ input,
                                       int n) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;
    const float slope = 0.01f;

    for (int i = tid; i < n; i += stride) {
        float v = input[i];
        output[i] = v > 0.0f ? v : slope * v;
    }
}

extern "C" void leaky_relu_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    // 16-byte alignment is guaranteed for=torch tensors created by
    // empty_like on float32 (data_ptr is 256-byte aligned in practice).
    const bool aligned = (reinterpret_cast<uintptr_t>(input) & 0xF) == 0 &&
                         (reinterpret_cast<uintptr_t>(output) & 0xF) == 0;

    if (aligned) {
        const int n_vec = size >> 2;              // floor(size / 4)
        const int rem  = size - (n_vec << 2);     // leftover elements

        // Fixed ~1024-block grid regardless of size: grid-stride loop covers
        // arbitrarily large N without an oversized launch. 104 SMs on C500.
        const int target_blocks = 1024;
        const int threads = 256;

        int blocks = target_blocks;
        if (n_vec < target_blocks) {
            blocks = (n_vec + threads - 1) / threads;
            if (blocks < 1) blocks = 1;
        }

        leaky_relu_vec4_impl<256><<<blocks, threads, 0, stream>>>(
            output, input, n_vec);

        if (rem > 0) {
            // Scalar cleanup for the trailing elements.
            int sblocks = (rem + 127) / 128;
            if (sblocks > 256) sblocks = 256;
            leaky_relu_scalar_impl<<<sblocks, 128, 0, stream>>>(
                output + (n_vec << 2), input + (n_vec << 2), rem);
        }
        (void)config;  // config reserved for future tuning
    } else {
        // Unaligned input: use the scalar path for the whole tensor.
        int blocks = (size + 255) / 256;
        if (blocks > 4096) blocks = 4096;
        leaky_relu_scalar_impl<<<blocks, 256, 0, stream>>>(output, input, size);
    }
}

