// Fused leaky_relu(x, 0.01) for MetaX C500 (warp size 64, 104 SMs).
//
// This is a pure memory-bound elementwise op on ~512M float elements (~2GB per
// tensor). The strategy is a single pass with:
//   - float4 vectorized loads/stores (4 elements per memory transaction)
//   - a FIXED grid of 1024 blocks (104 SMs -> ~8 waves) with a grid-stride
//     loop, avoiding the one-thread-per-element grid that measured only
//     ~338-642 GB/s on this device.
//   - branch-free math: max(x, 0.01*x)  ==  leaky_relu(x, 0.01) for slope>0,
//     chosen because the select only depends on the sign bit of x, so no
//     SFU chain is introduced and the arithmetic hides behind memory traffic.
// Aligned tail handling keeps the vectorized body free of bounds checks.

#include <cuda_runtime.h>

// Treat 4 consecutive floats as one 128-bit transaction.
#define FLOAT4_CAST(ptr) (*reinterpret_cast<float4*>((ptr)))

__device__ __forceinline__ float4 leaky_relu4(float4 v) {
    float4 out;
    out.x = fmaxf(v.x, 0.01f * v.x);
    out.y = fmaxf(v.y, 0.01f * v.y);
    out.z = fmaxf(v.z, 0.01f * v.z);
    out.w = fmaxf(v.w, 0.01f * v.w);
    return out;
}

// BLOCK=256 threads, VEC=4 floats/thread -> 1024 floats per block iteration.
// GRID=1024 blocks -> 262144 floats per grid stride; ~1958 strides for 512M.
template<int BLOCK>
__global__ void leaky_relu_kernel_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    unsigned long long count      // number of FLOAT elements
) {
    const unsigned long long vec_count = count >> 2;  // full float4 lanes
    const int tid = blockIdx.x * BLOCK + threadIdx.x;
    const int stride = BLOCK * gridDim.x;

    // Vectorized body: no per-thread bounds check beyond the stride loop.
    for (unsigned long long i = tid; i < vec_count; i += stride) {
        float4 v = FLOAT4_CAST(input + (i << 2));
        FLOAT4_CAST(output + (i << 2)) = leaky_relu4(v);
    }

    // Tail: the (0..3) trailing elements that don't fill a float4.
    const unsigned long long tail_base = vec_count << 2;
    const int tail = (int)(count - tail_base);
    if (tail > 0 && tid < tail) {
        float v = input[tail_base + tid];
        output[tail_base + tid] = fmaxf(v, 0.01f * v);
    }
}

extern "C" void leaky_relu_kernel_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    cudaStream_t stream
) {
    const int BLOCK = 256;
    const int GRID = 1024;
    leaky_relu_kernel_impl<BLOCK><<<GRID, BLOCK, 0, stream>>>(
        output, input, size);
}

