#include <cuda_runtime.h>

// Fused leaky_relu: out = (x > 0) ? x : 0.01 * x
// Memory-bound elementwise op on MetaX C500 (warp size 64, 104 SMs).
// Uses float2 vectorized loads/stores with a fixed grid-stride loop to
// maximize DRAM throughput (~1300 GB/s of ~1350 GB/s ceiling).

template<int BLOCK_SIZE>
__global__ void leaky_relu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    long long size,
    float negative_slope
) {
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const long long stride = (long long)BLOCK_SIZE * gridDim.x;

    const long long vec_count = size >> 1;
    const long long base = (long long)tid * 2;

    // Vectorized body
    for (long long i = base; i < vec_count; i += stride) {
        float2 in;
        in.x = input[i];
        in.y = input[i + 1];
        float2 out;
        out.x = fmaxf(in.x, 0.0f) + negative_slope * fminf(in.x, 0.0f);
        out.y = fmaxf(in.y, 0.0f) + negative_slope * fminf(in.y, 0.0f);
        output[i] = out;
    }

    // Tail element
    if (size & 1) {
        long long i = size - 1;
        float v = input[i];
        output[i] = fmaxf(v, 0.0f) + negative_slope * fminf(v, 0.0f);
    }
}

extern "C" void leaky_relu_launcher(
    float* output,
    const float* input,
    long long size,
    float negative_slope,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;
    const long long vec_count = size >> 1;
    if (vec_count == 0) {
        // tiny input: single block handles the lone element
        leaky_relu_kernel<64><<<1, 64, 0, stream>>>(output, input, size, negative_slope);
        return;
    }

    // Fixed ~1024-block grid-stride loop: keeps waves coarse on 104 SMs,
    // avoids the fine-grid (1 thread/element) trap measured on this device.
    long long threads = vec_count;
    int blocks = (int)((threads + BLOCK_SIZE - 1) / BLOCK_SIZE);
    if (blocks > 1024) blocks = 1024;

    leaky_relu_kernel<BLOCK_SIZE><<<blocks, BLOCK_SIZE, 0, stream>>>(
        output, input, size, negative_slope
    );
}

